  function mixParse(raw) {
    const o = {};
    if (!raw) return o;
    const parts = raw.split(',');
    for (let i = 0; i < parts.length; i++) {
      const eq = parts[i].indexOf('=');
      if (eq > 0) o[parts[i].slice(0, eq)] = parts[i].slice(eq + 1);
    }
    return o;
  }

