  let pyGroups = null;

  function buildPyGroups() {
    if (pyGroups || !pinyinReady) return;
    const fn = pyFn();
    if (!fn) return;
    try {
      const arr = fn(PY_CORPUS, { toneType: 'num', type: 'array' });
      if (!Array.isArray(arr) || arr.length !== PY_CORPUS.length) return;
      const noTone = {};
      const byTone = {};
      for (let i = 0; i < PY_CORPUS.length; i++) {
        const m = /^([a-z:ü]+)([1-5])?$/.exec(String(arr[i] || ''));
        if (!m) continue;
        const ch = PY_CORPUS[i];
        const key = m[1] + (m[2] || '5');
        (noTone[m[1]] || (noTone[m[1]] = [])).push(ch);
        (byTone[key] || (byTone[key] = [])).push(ch);
      }

      const byFreq = function (a, b) { return freqRankOf(a) - freqRankOf(b); };
      for (const k in noTone) noTone[k].sort(byFreq);
      for (const k in byTone) byTone[k].sort(byFreq);
      pyGroups = { noTone: noTone, byTone: byTone };
    } catch (e) {  }
  }

  function contextReadings(value) {
    const fn = pyFn();
    if (!fn) return null;
    try {
      const out = [];
      for (const part of value.split(CJK_SPLIT)) {
        if (!part) continue;
        if (CJK_TEST.test(part)) {

          if (part.length > 200) {
            for (let s = 0; s < part.length; s += 200) {
              const seg = part.slice(s, s + 200);
              const arr = fn(seg, { toneType: 'num', type: 'array' });
              for (let i = 0; i < seg.length; i++) out.push(arr[i] || null);
            }
          } else {
            const arr = fn(part, { toneType: 'num', type: 'array' });
            for (let i = 0; i < part.length; i++) out.push(arr[i] || null);
          }
        } else {
          for (let i = 0; i < part.length; i++) out.push(null);
        }
      }
      return out.length === value.length ? out : null;
    } catch (e) { return null; }
  }

  function pickHomophone(ch, reading, rng) {
    if (pyGroups) {
      const m = /^([a-z:ü]+)([1-5])?$/.exec(String(reading || ''));
      if (m) {
        let pool = null;
        if (settings.toneMatch === 'strict' && m[2]) pool = pyGroups.byTone[m[1] + m[2]];
        if (!pool || !pool.length) pool = pyGroups.noTone[m[1]] || null;
        if (pool) {
          const cands = pool.filter(function (c) { return c !== ch; });
          if (cands.length) {

            const k = settings.hbSmart ? Math.min(cands.length, 5) : cands.length;
            return cands[(rng() * k) | 0];
          }
        }
        return null;
      }
    }

    const pys = CHAR_PY[ch];
    if (!pys) return null;
    const py = pys[(rng() * pys.length) | 0];
    const candidates = [];
    for (const c of (PY_RAW[py] || '')) if (c !== ch) candidates.push(c);
    if (!candidates.length) return null;
    return candidates[(rng() * candidates.length) | 0];
  }

