  let tradTokenCache = null;
  function tradTokenKeys() {
    if (!tradTokenCache) {
      tradTokenCache = Object.keys(TRAD_PHRASE_MAP)
        .concat(Object.keys(TRAD_MAP))
        .sort(function (a, b) { return b.length - a.length; });
    }
    return tradTokenCache;
  }
  function traditionalTokenAt(text, at) {
    const keys = tradTokenKeys();
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      if (!text.startsWith(key, at)) continue;
      const dst = key.length > 1 ? TRAD_PHRASE_MAP[key] : TRAD_MAP[key];
      if (dst) return { src: key, dst: dst };
    }
    const codePoint = text.codePointAt(at);
    const ch = String.fromCodePoint(codePoint);
    return { src: ch, dst: ch };
  }
  const TRAD_REVERSE_MAP = (function () {
    const out = {};
    Object.keys(TRAD_PHRASE_MAP).forEach(function (key) {
      const dst = TRAD_PHRASE_MAP[key];
      if (dst && !Object.prototype.hasOwnProperty.call(out, dst)) out[dst] = key;
    });
    Object.keys(TRAD_MAP).forEach(function (key) {
      const dst = TRAD_MAP[key];
      if (dst && !Object.prototype.hasOwnProperty.call(out, dst)) out[dst] = key;
    });
    return out;
  })();
  let tradReverseKeysCache = null;
  function tradReverseKeys() {
    if (!tradReverseKeysCache) {
      tradReverseKeysCache = Object.keys(TRAD_REVERSE_MAP)
        .sort(function (a, b) { return b.length - a.length; });
    }
    return tradReverseKeysCache;
  }
  function simplifyTraditionalText(text) {
    const source = String(text || '');
    const keys = tradReverseKeys();
    let out = '';
    let at = 0;
    while (at < source.length) {
      let hit = '';
      for (let i = 0; i < keys.length; i++) {
        if (source.startsWith(keys[i], at)) { hit = keys[i]; break; }
      }
      if (hit) {
        out += TRAD_REVERSE_MAP[hit];
        at += hit.length;
        continue;
      }
      const codePoint = source.codePointAt(at);
      const ch = String.fromCodePoint(codePoint);
      out += ch;
      at += ch.length;
    }
    return out;
  }

