        const call = part && part.functionCall;
        if (call && call.args && settings.rspTool !== false) {
          if (!call.name) { keep.push(part); continue; }
          if (rspIsDbTool(call.name)) { st.dbTool = true; keep.push(part); continue; }
          const scan = rspScanValues(rspArgsText(call.args));
          if (scan.best && scan.best.length >= rspMin()) {
            pieces.push(rspTake(st, scan.best));
            if (settings.rspTrimTool === true) { touched = true; continue; }
          }
        }
        if (part && typeof part.text === 'string' && part.text) {
          st.plain += part.text;
          if (st.tool && settings.rspDual !== false) { touched = true; continue; }
          st.plainSent += part.text.length;
          keep.push(part);
          continue;
        }
        keep.push(part);
      }
      if (fin) {
        const tail = rspTail(st);
        if (tail) pieces.push(tail);
      }
      if (pieces.length) {
        keep.unshift({ text: pieces.join('') });
        cand.content.parts = keep;
        touched = true;
      }
    }
    return touched;
  }

  function rspPatchAnthropicMessage(obj, st) {
    if (!Array.isArray(obj.content) || settings.rspTool === false) return false;
    const keep = [];
    let best = '';
    let keptTool = false;
    for (let i = 0; i < obj.content.length; i++) {
      const part = obj.content[i];
      if (part && part.type === 'tool_use' && part.input !== undefined) {
        if (!part.name) { keep.push(part); continue; }
        if (rspIsDbTool(part.name)) { st.dbTool = true; keep.push(part); continue; }
        const scan = rspScanValues(rspArgsText(part.input));
        if (scan.best.length > best.length) best = scan.best;
        if (settings.rspTrimTool === true) continue;
        keptTool = true;
      }
      if (part && part.type === 'text' && typeof part.text === 'string') st.plain += part.text;
      keep.push(part);
    }
    if (!best || best.length < rspMin()) return false;
    if (settings.rspDual !== false && st.plain.length > best.length) return false;
    const dupText = st.plain.trim() === best.trim();
    if (!dupText) keep.unshift({ type: 'text', text: best });
    obj.content = keep;
    if (obj.stop_reason === 'tool_use' && !st.dbTool && !keptTool) obj.stop_reason = 'end_turn';
    return true;
  }

  function rspPatchAnthropic(obj, st) {
    if (obj.type === 'content_block_start' && obj.content_block) {
      const cb = obj.content_block;
      if (settings.rspTool === false) return false;
      if (cb.type === 'tool_use') {
        if (settings.rspTrimTool !== true) return false;
        const key = 'a:' + (typeof obj.index === 'number' ? obj.index : 0);
        if (cb.name) st.toolNames[key] = cb.name;
        const nm0 = cb.name || st.toolNames[key] || '';
        if (!nm0) return false;
        if (rspIsDbTool(nm0)) { st.dbTool = true; return false; }
        const initial = rspArgsText(cb.input);
        const initialBest = initial ? rspScanValues(initial).best : '';
        const isStory = /^thp_publish_story$/i.test(nm0);


        if (!isStory && (!initialBest || initialBest.length < rspMin())) return false;
        st.textBlocks[key] = 1;
        let add = '';
        if (initial) add = rspTake(st, rspFeed(rspSlot(st, key), initial, st));
        obj.content_block = { type: 'text', text: add };
        return true;
      }
      return false;
    }
    if (obj.type === 'content_block_delta' && obj.delta) {
      const d = obj.delta;
      if (d.type === 'input_json_delta' && typeof d.partial_json === 'string') {
        if (settings.rspTool === false || settings.rspTrimTool !== true) return false;
        const key = 'a:' + (typeof obj.index === 'number' ? obj.index : 0);
        const nm = st.toolNames[key] || '';
        if (!nm) return false;
        if (!st.textBlocks[key]) return false;
        if (rspIsDbTool(nm)) { st.dbTool = true; return false; }
        const slot = rspSlot(st, key);
        const add = rspTake(st, rspFeed(slot, d.partial_json, st));
        if (add) { obj.delta = { type: 'text_delta', text: add }; return true; }
        if (st.textBlocks[key]) { obj.delta = { type: 'text_delta', text: '' }; return true; }
      } else if (d.type === 'text_delta' && typeof d.text === 'string') {
        st.plain += d.text;
        if (st.tool && settings.rspDual !== false) {
          obj.delta = { type: 'text_delta', text: '' };
          return true;
        }
        st.plainSent += d.text.length;
      }
    }
    if (obj.type === 'message_delta' && obj.delta && obj.delta.stop_reason) {
      st.finished = true;
      if (obj.delta.stop_reason === 'max_tokens') { st.cut = true; st.cutReason = 'length'; }
      else if (obj.delta.stop_reason === 'refusal') { st.cut = true; st.cutReason = 'filtered'; }
      if (obj.delta.stop_reason === 'tool_use' && !st.dbTool && settings.rspTool !== false &&
        (st.tool || st.toolTrimmed)) {
        obj.delta.stop_reason = 'end_turn';
        return true;
      }
    }
    return false;
  }

  function rspPatchResponses(obj, st) {
    if (obj.type === 'response.completed') st.finished = true;
    if (obj.type === 'response.incomplete') { st.finished = true; st.cut = true; st.cutReason = 'incomplete'; }
    if ((obj.type === 'response.output_item.added' || obj.type === 'response.output_item.done') && obj.item) {
      const it = obj.item;
      if (it.type === 'function_call') {
        const key = 'r:' + (it.id || obj.output_index || 0);
        if (it.name) st.toolNames[key] = it.name;
        if (rspIsDbTool(it.name)) st.dbTool = true;
      }
      return false;
    }
    if (obj.type === 'response.function_call_arguments.delta' && typeof obj.delta === 'string') {
      if (settings.rspTool === false) return false;
      const key = 'r:' + (obj.item_id || obj.output_index || 0);
      const nm = st.toolNames[key] || '';
      if (!nm) return false;
      if (rspIsDbTool(nm)) { st.dbTool = true; return false; }
      const slot = rspSlot(st, key);
      const add = rspTake(st, rspFeed(slot, obj.delta, st));
      if (add) st.textItems[key] = 1;
      if (!add && !st.textItems[key]) return false;
      obj.type = 'response.output_text.delta';
      obj.delta = add || '';
      delete obj.item_id;
      return true;
    }
    if (obj.type === 'response.output_text.delta' && typeof obj.delta === 'string') {
      st.plain += obj.delta;
      if (st.tool && settings.rspDual !== false) { obj.delta = ''; return true; }
      st.plainSent += obj.delta.length;
      return false;
    }
    const holder = (obj.response && Array.isArray(obj.response.output)) ? obj.response : obj;
    if (Array.isArray(holder.output)) {
      const keep = [];
      let best = '';
      let itemPlain = '';
      for (let i = 0; i < holder.output.length; i++) {
        const item = holder.output[i];
        if (item && item.type === 'function_call') {
          if (settings.rspTool === false) { keep.push(item); continue; }
          if (!item.name) { keep.push(item); continue; }
          if (rspIsDbTool(item.name)) { st.dbTool = true; keep.push(item); continue; }
          const scan = rspScanValues(rspArgsText(item.arguments));
          if (scan.best.length > best.length) best = scan.best;
          if (settings.rspTrimTool === true) continue;
        }
        if (item && item.type === 'message' && Array.isArray(item.content)) {
          for (let k = 0; k < item.content.length; k++) {
            const p = item.content[k];
            if (p && typeof p.text === 'string') itemPlain += p.text;
          }
        }
        keep.push(item);
      }
      if (typeof holder.output_text === 'string') st.plain += holder.output_text;
      else if (itemPlain) st.plain += itemPlain;
      if (!best || best.length < rspMin()) return false;
      if (settings.rspDual !== false && st.plain.length > best.length) return false;
      const dupText = st.plain.trim() === best.trim();
      if (!dupText) keep.unshift({ type: 'message', role: 'assistant', content: [{ type: 'output_text', text: best }] });
      holder.output = keep;
      holder.output_text = best;
      return true;
    }
    return false;
  }

  function rspPatchOllama(obj, st, key) {
    const v = obj[key];
    if (obj.done === true || (v && v.done === true)) st.finished = true;
    if (obj.done_reason === 'length' || (v && v.done_reason === 'length')) {
      st.cut = true;
      st.cutReason = 'length';
    }
    if (v && typeof v === 'object' && Array.isArray(v.tool_calls) && settings.rspTool !== false) {
      let best = '';
      const keep = [];
      for (let i = 0; i < v.tool_calls.length; i++) {
        const call = v.tool_calls[i];
        const fn = call && call.function;
        if (!fn) { keep.push(call); continue; }
        if (!fn.name) { keep.push(call); continue; }
        if (rspIsDbTool(fn.name)) { st.dbTool = true; keep.push(call); continue; }
        const scan = rspScanValues(rspArgsText(fn.arguments));
        if (scan.best.length > best.length) best = scan.best;
        if (settings.rspTrimTool !== true) keep.push(call);
      }
      if (best && best.length >= rspMin()) {
        const cur = typeof v.content === 'string' ? v.content : '';
        if (settings.rspDual !== false && cur.length > best.length) {
          if (settings.rspTrimTool !== true) return false;
          if (keep.length) v.tool_calls = keep;
          else delete v.tool_calls;
          return true;
        }
        v.content = settings.rspDual !== false ? best : (cur + best);
        if (settings.rspTrimTool === true) {
          if (keep.length) v.tool_calls = keep;
          else delete v.tool_calls;
        }
        return true;
      }
      return false;
    }
    if (typeof v === 'string') { st.plain += v; st.plainSent += v.length; }
    return false;
  }

  function rspMarkFormat(st, name) {
    if (!st.format) st.format = name;
    rspState.stats.lastFormat = name;
  }

  function rspPatchAny(obj, st) {
    let touched = false;
    if (Array.isArray(obj.choices)) {
      rspMarkFormat(st, 'openai');
      touched = rspPatchChoices(obj, st) || touched;
    } else if (Array.isArray(obj.candidates)) {
      rspMarkFormat(st, 'gemini');
      touched = rspPatchGoogle(obj, st) || touched;
    } else if ((typeof obj.type === 'string' && obj.type.indexOf('response.') === 0) ||
      Array.isArray(obj.output) || typeof obj.output_text === 'string') {
      rspMarkFormat(st, 'responses');
      touched = rspPatchResponses(obj, st) || touched;
    } else if (typeof obj.type === 'string' &&
      (obj.type.indexOf('content_block_') === 0 || obj.type === 'message_delta')) {
      rspMarkFormat(st, 'anthropic');
      touched = rspPatchAnthropic(obj, st) || touched;
    } else if (Array.isArray(obj.content)) {
      rspMarkFormat(st, 'anthropic');
      touched = rspPatchAnthropicMessage(obj, st) || touched;
    } else if (obj.message && typeof obj.message === 'object') {
      rspMarkFormat(st, 'ollama');
      touched = rspPatchOllama(obj, st, 'message') || touched;
    } else if (typeof obj.response === 'string') {
      rspMarkFormat(st, 'ollama');
      touched = rspPatchOllama(obj, st, 'response') || touched;
    }
    return touched;
  }

  function rspRewritePayload(payload, st) {
    const raw = String(payload == null ? '' : payload);
    const t = raw.trim();
    if (!t) return raw;
    if (t === '[DONE]') { st.sawDone = true; return raw; }
    let obj;
    try { obj = JSON.parse(t); } catch (e) { return raw; }
    if (!obj || typeof obj !== 'object') return raw;
    if (!rspPatchAny(obj, st)) return raw;
    rspState.stats.hits++;
    return JSON.stringify(obj);
  }

  function rspRewriteJsonBody(text) {
    let obj;
    try { obj = JSON.parse(text); } catch (e) { return text; }
    if (!obj || typeof obj !== 'object') return text;
    const st = rspSession();
    let touched = false;
    let choicesSeen = false;
    let candidatesSeen = false;
    if (Array.isArray(obj.choices) && obj.choices.length <= 1) {
      for (let i = 0; i < obj.choices.length; i++) {
        const ch = obj.choices[i];
        const msg = ch && ch.message;
        if (!msg || typeof msg !== 'object') continue;
        choicesSeen = true;
        if (settings.rspTool === false) continue;
        const plain = rspText(msg.content);
        let best = '';
        const keep = [];
        let dbTool = false;
        let fcDb = false;

        if (Array.isArray(msg.tool_calls)) {
          for (let k = 0; k < msg.tool_calls.length; k++) {
            const call = msg.tool_calls[k];
            const fn = call && call.function;
            if (!fn) { keep.push(call); continue; }
            if (!fn.name) { keep.push(call); continue; }
            if (rspIsDbTool(fn.name)) { dbTool = true; keep.push(call); continue; }
            const args = rspArgsText(fn.arguments);
            if (args) {
              const scan = rspScanValues(args);
              if (scan.best.length > best.length) best = scan.best;
            }
            if (settings.rspTrimTool !== true) keep.push(call);
          }
        }
        if (msg.function_call && typeof msg.function_call === 'object') {
          const fn = msg.function_call;
          if (!fn.name) {

          } else if (rspIsDbTool(fn.name)) {
            dbTool = true;
            fcDb = true;
          } else {
            const scan = rspScanValues(rspArgsText(fn.arguments));
            if (scan.best.length > best.length) best = scan.best;
          }
        }
        if (!best || best.length < rspMin()) continue;

        const trim = settings.rspTrimTool === true;
        const setTools = function () {
          if (Array.isArray(msg.tool_calls)) {
            if (keep.length) msg.tool_calls = keep;
            else delete msg.tool_calls;
          }
          if (msg.function_call && !fcDb) delete msg.function_call;
        };

        if (settings.rspDual !== false && plain.length > best.length) {
          if (trim) { setTools(); touched = true; }
          continue;
        }
        msg.content = best;
        if (trim) setTools();
        if ((ch.finish_reason === 'tool_calls' || ch.finish_reason === 'function_call') && !dbTool) {
          ch.finish_reason = 'stop';
        }
        touched = true;
        rspState.stats.hits++;
      }
    }
    if (Array.isArray(obj.candidates) && obj.candidates.length <= 1) {
      for (let i = 0; i < obj.candidates.length; i++) {
        const cand = obj.candidates[i];
        const parts = cand && cand.content && cand.content.parts;
        if (!Array.isArray(parts)) continue;
        candidatesSeen = true;
        if (settings.rspTool === false) continue;
        const keep = [];
        let best = '';
        let plain = '';
        for (let k = 0; k < parts.length; k++) {
          const part = parts[k];
          const call = part && part.functionCall;
          if (call && call.args) {
            if (!call.name) { keep.push(part); continue; }
            if (rspIsDbTool(call.name)) { keep.push(part); continue; }
            const scan = rspScanValues(rspArgsText(call.args));
            if (scan.best.length > best.length) best = scan.best;
            if (settings.rspTrimTool === true) continue;
          }
          if (part && typeof part.text === 'string') plain += part.text;
          keep.push(part);
        }
        if (!best || best.length < rspMin()) continue;
        if (settings.rspDual !== false && plain.length > best.length) continue;
        cand.content.parts = [{ text: best }].concat(keep);
        touched = true;
        rspState.stats.hits++;
      }
    }

    if (!touched && !choicesSeen && !candidatesSeen) touched = rspPatchAny(obj, st);
    return touched ? JSON.stringify(obj) : text;
  }

  function rspHeaders(resp) {
    let h;
    try { h = new Headers(resp.headers); } catch (e) { return resp.headers; }

    try { h.delete('content-length'); } catch (e) {}
    try { h.delete('content-encoding'); } catch (e) {}
    return h;
  }

  function rspTransformEvent(evt, st) {
    const lines = String(evt).split('\n');
    const out = [];
    let evtName = '';
    let dataLines = [];

    const flushData = function () {
      if (!dataLines.length) return;
      const raw = dataLines.join('\n');
      const t = raw.trim();
      let patched = '';
      if (t === '[DONE]') {
        st.sawDone = true;
        st.donePending = true;
      } else if (t) {
        try {
          const o = JSON.parse(t);
          if (o && typeof o === 'object' && rspPatchAny(o, st)) {
            patched = JSON.stringify(o);
            rspState.stats.hits++;
          }
        } catch (e) {}
      }
      if (patched) {
        out.push('data: ' + patched);
      } else if (t === '[DONE]') {

      } else {
        for (let k = 0; k < dataLines.length; k++) out.push('data: ' + dataLines[k]);
      }
      dataLines = [];
    };

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (line.indexOf('event:') === 0) {
        flushData();
        evtName = line.slice(6).trim();
        out.push(line);
        continue;
      }
      if (line.indexOf('data:') === 0) {
        dataLines.push(line.slice(5).replace(/^ /, ''));
        continue;
      }
      flushData();
      out.push(line);
    }
    flushData();

    if (evtName) {
      for (let i = out.length - 1; i >= 0; i--) {
        if (out[i].indexOf('data:') !== 0) continue;
        try {
          const o = JSON.parse(out[i].slice(6));
          if (o && typeof o.type === 'string' && o.type !== evtName) {
            for (let k = 0; k < out.length; k++) {
              if (out[k].indexOf('event:') === 0) { out[k] = 'event: ' + o.type; break; }
            }
          }
        } catch (e) {}
        break;
      }
    }
    return out.join('\n');
  }

  function rspWrapSse(resp) {
    const dec = new TextDecoder();
    const enc = new TextEncoder();
    const st = rspSession();
    let buf = '';
    const stream = new TransformStream({
      transform: function (chunk, ctl) {
        buf += dec.decode(chunk, { stream: true });

        if (buf.charAt(buf.length - 1) === '\r') {
          buf = buf.slice(0, -1).replace(/\r\n/g, '\n').replace(/\r/g, '\n') + '\r';
        } else {
          buf = buf.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        }
        let cut;
        while ((cut = buf.indexOf('\n\n')) !== -1) {
          const evt = buf.slice(0, cut);
          buf = buf.slice(cut + 2);
          const transformed = rspTransformEvent(evt, st);
          if (transformed) ctl.enqueue(enc.encode(transformed + '\n\n'));
        }
      },
      flush: function (ctl) {
        buf += dec.decode();
        buf = buf.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        if (buf.trim()) {
          const transformed = rspTransformEvent(buf, st);
          if (transformed) ctl.enqueue(enc.encode(transformed + '\n\n'));
        }

        const pendOut = rspFlushPending(st);
        if (pendOut) ctl.enqueue(enc.encode('data: ' + JSON.stringify(rspSseTailPayload(st, pendOut)) + '\n\n'));

        const rest = st.tool ? '' : rspTake(st, rspDrain(st));
        if (rest) {
          ctl.enqueue(enc.encode('data: ' + JSON.stringify(rspSseTailPayload(st, rest)) + '\n\n'));
        }
        const tail = rspTail(st);
        if (tail) {
          ctl.enqueue(enc.encode('data: ' + JSON.stringify(rspSseTailPayload(st, tail)) + '\n\n'));
        }
        if (st.donePending) {
          st.donePending = false;
          ctl.enqueue(enc.encode('data: [DONE]\n\n'));
        }

        const cutReason = st.cutReason || '';
        const ended = (st.sawDone || st.finished) && !cutReason;
        const cutKind = cutReason || (ended ? 'normal' : rspCutKind(st));
        if (!ended) { rspState.stats.cut++; rspState.stats.lastCutKind = cutKind; }
        if (st.capped) {
          rspState.stats.capped++;
          rspDiagPush('cap', { limit: RSP_CAP, format: st.format });
          rspLog('超长保护', '工具参数超过 ' + RSP_CAP + ' 字，超出部分未还原');
        }
        rspState.stats.chars += st.tool.length;
        rspDiagPush('stream-end', {
          format: st.format, hit: st.tool.length > 0, chars: st.tool.length,
          cut: !ended, cutKind: cutKind, sawDone: st.sawDone, finished: st.finished, capped: st.capped
        });
        if (settings.rspLog === true && st.tool) {
          rspLog('流结束', '还原 ' + st.tool.length + ' 字', ended ? '正常收尾' : '断流');
        }
      }
    });

    try {
      resp.body.pipeTo(stream.writable).catch(function (err) {
        rspLog('流处理失败，已中断下游连接', err && err.message);
        rspDiagPush('stream-error', { reason: 'pipe-failed' });
        try { if (stream.writable.abort) stream.writable.abort(err); } catch (e2) {}
      });
    } catch (e) {}
    return new Response(stream.readable, {
      status: resp.status,
      statusText: resp.statusText,
      headers: rspHeaders(resp)
    });
  }

  function rspWrapJson(resp, text) {
    const out = rspRewriteJsonBody(text);
    if (out === text) return resp;
    rspState.stats.chars += out.length;
    rspDiagPush('json', { format: rspState.stats.lastFormat, hit: true, chars: out.length });
    return new Response(out, {
      status: resp.status,
      statusText: resp.statusText,
      headers: rspHeaders(resp)
    });
  }

  function rspWrapNdjson(resp) {
    const dec = new TextDecoder();
    const enc = new TextEncoder();
    const st = rspSession();
    let buf = '';
    const one = function (line) {
      const t = line.trim();
      if (t === '[DONE]') { st.sawDone = true; st.donePending = true; return ''; }
      if (!t || t.charAt(0) !== '{') return line;
      return rspRewritePayload(t, st);
    };
    const stream = new TransformStream({
      transform: function (chunk, ctl) {
        buf += dec.decode(chunk, { stream: true });
        let cut;
        while ((cut = buf.indexOf('\n')) !== -1) {
          const line = buf.slice(0, cut);
          buf = buf.slice(cut + 1);
          ctl.enqueue(enc.encode(one(line) + '\n'));
        }
      },
      flush: function (ctl) {
        buf += dec.decode();
        if (buf.trim()) ctl.enqueue(enc.encode(one(buf) + '\n'));
        const pendOut = rspFlushPending(st);
        if (pendOut) ctl.enqueue(enc.encode(JSON.stringify({ choices: [{ index: 0, delta: { content: pendOut }, finish_reason: null }] }) + '\n'));
        if (st.donePending) {
          st.donePending = false;
          ctl.enqueue(enc.encode('[DONE]\n'));
        }
        rspState.stats.chars += st.tool.length;
        const cutReason = st.cutReason || '';
        const ended = (st.sawDone || st.finished) && !cutReason;
        const cutKind = cutReason || (ended ? 'normal' : rspCutKind(st));
        if (!ended) { rspState.stats.cut++; rspState.stats.lastCutKind = cutKind; }
        if (st.capped) {
          rspState.stats.capped++;
          rspDiagPush('cap', { limit: RSP_CAP, format: st.format });
          rspLog('超长保护', '工具参数超过 ' + RSP_CAP + ' 字，超出部分未还原');
        }
        rspDiagPush('ndjson-end', {
          format: st.format, hit: st.tool.length > 0, chars: st.tool.length,
          cut: !ended, cutKind: cutKind, sawDone: st.sawDone, finished: st.finished, capped: st.capped
        });
      }
    });
    try {
      resp.body.pipeTo(stream.writable).catch(function (err) {
        rspLog('NDJSON 处理失败，已中断下游连接', err && err.message);
        try { if (stream.writable.abort) stream.writable.abort(err); } catch (e2) {}
      });
    } catch (e) {}
    return new Response(stream.readable, {
      status: resp.status,
      statusText: resp.statusText,
      headers: rspHeaders(resp)
    });
  }

  async function rspIntercept(orig, thisArg, args) {
    const resp = await orig.apply(thisArg, args);
    try {
      if (!resp || !resp.ok) return resp;
      if (resp.status === 204 || resp.status === 205 || resp.status === 304) return resp;
      if (!rspOn()) return resp;
      if (settings.rspTool === false && settings.rspDual === false) return resp;
      rspState.stats.runs++;
      const ct = String((resp.headers && resp.headers.get('content-type')) || '');
      diagFeature('回应增强', true, 'HTTP ' + resp.status + ' · ' + (ct.split(';')[0] || '未知类型'));
      if (/ndjson/i.test(ct)) {
        if (!resp.body) return resp;
        rspDiagPush('response', { status: resp.status, contentType: 'ndjson', hasBody: true });
        return rspWrapNdjson(resp);
      }
      if (/text\/event-stream/i.test(ct)) {
        if (!resp.body) return resp;
        rspDiagPush('response', { status: resp.status, contentType: 'sse', hasBody: true });
        return rspWrapSse(resp);
      }
      if (/json/i.test(ct)) {
        const txt = await resp.clone().text();
        if (txt && txt.trim().charAt(0) === '{') return rspWrapJson(resp, txt);
        rspDiagPush('response', { status: resp.status, contentType: 'json', hasBody: true, reason: 'not-json-object' });
        return resp;
      }
      rspDiagPush('response', {
        status: resp.status, contentType: ct.split(';')[0],
        hasBody: !!resp.body, reason: 'unsupported-type'
      });
      return resp;
    } catch (e) {
      rspLog('处理失败，已原样放行', e && e.message);
      rspDiagPush('response', { reason: 'exception', ok: false });
      return resp;
    }
  }

  function rspUrlOf(input) {
    try {
      if (typeof input === 'string') return input;
      if (input && typeof input.url === 'string') return input.url;
      if (input && typeof input.href === 'string') return input.href;
    } catch (e) {}
    return '';
  }

  function rspTargetWin() {
    try { if (host && typeof host.fetch === 'function') return host; } catch (e) {}
    try { if (typeof window !== 'undefined' && typeof window.fetch === 'function') return window; } catch (e) {}
    return null;
  }

  function rspInstall() {
    const win = rspTargetWin();
    if (!win) return false;

    if (rspState.installed && rspState.wrapped && rspState.target === win) {
      rspState.enabled = true;
      try { rspState.wrapped[RSP_KEY].enabled = true; } catch (e) {}
      return true;
    }
    const cur = win.fetch;

    if (cur && cur[RSP_KEY] && cur[RSP_KEY].owner === 'pinyin-ime') {
      try { cur[RSP_KEY].enabled = false; } catch (e) {}
    }
    const orig = cur;
    const wrapped = function () {
      let mark = null;
      try { mark = wrapped[RSP_KEY]; } catch (e) {}
      if (mark && mark.enabled === true) {
        try {
          const url = rspUrlOf(arguments[0]);
          if (url && RSP_EP.test(url)) return rspIntercept(orig, this, arguments);
        } catch (e) {}
      }
      return orig.apply(this, arguments);
    };
    wrapped[RSP_KEY] = { owner: 'pinyin-ime', instanceId: RSP_INSTANCE_ID, original: orig, enabled: true };
    try { win.fetch = wrapped; } catch (e) { return false; }
    rspState.installed = true;
    rspState.enabled = true;
    rspState.target = win;
    rspState.wrapped = wrapped;
    rspState.original = orig;
    rspLog('已开启');
    rspDiagPush('install', { ok: true });
    return true;
  }

  function rspUninstall() {
    rspState.enabled = false;
    try {
      const win = rspState.target;
      if (win && rspState.wrapped) {
        try { rspState.wrapped[RSP_KEY].enabled = false; } catch (e) {}

        if (win.fetch === rspState.wrapped) {
        win.fetch = rspState.original;
          rspState.installed = false;
          rspState.wrapped = null;
          rspState.original = null;
          rspState.target = null;
      }
      }
    } catch (e) {}
    rspLog('已关闭');
    rspDiagPush('uninstall', { ok: true });
  }

  function rspSync() {
    if (rspOn()) rspInstall();
    else rspUninstall();
    rspRenderStats();
  }

  function rspPresetOwns(data) {
    if (settings.rspArbiter === false) return false;
    try {
      const tools = data && data.tools;
      if (Array.isArray(tools)) {
        for (let i = 0; i < tools.length; i++) {
          const d = tools[i] && tools[i].function && tools[i].function.description;
          if (typeof d === 'string' && d.length > 20000) {
            rspDiagPush('arbiter', { arbiter: true, reason: 'long-tool-description' });
            return true;
          }
        }
      }
      const arr = (data && data.prompt) || (data && data.messages);
      if (Array.isArray(arr) && arr.length) {
        const t = rspText(arr[arr.length - 1] && arr[arr.length - 1].content).trim();
        if (t && /"function"\s*:\s*$/.test(t)) {
          rspDiagPush('arbiter', { arbiter: true, reason: 'unclosed-function-call' });
          return true;
        }
      }
    } catch (e) {}
    return false;
  }

  function rspSceneLabel() {
    const id = String(settings.rspScene || '');
    if (id === 'empty') return '防空回';
    if (id === 'cut') return '防截断加强';
    if (id === 'full') return '还原 + 仲裁';
    return '自定义';
  }

