      ['当前场景', rspSceneLabel()],
      ['总开关', onOff(settings.rspEnabled)],
      ['工具还原', onOff(settings.rspTool)],
      ['双通道取最长', onOff(settings.rspDual)],
      ['移除工具调用', onOff(settings.rspTrimTool)],
      ['请求仲裁', onOff(settings.rspArbiter)],
      ['最小长度', settings.rspMinChars + ' 字'],
      ['混淆', settings.hellEnabled === true ? '炼狱接管' : onOff(settings.obfEnabled)],
      ['防路由', settings.arEnabled !== true ? '关'
        : ('开 · ' + (arLast.profile || settings.arProfile) + (arLast.ran ? (' · 上次 +' + arLast.added + ' 字') : ' · 待运行'))],
      ['网关层', arActive ? '由防路由接管'
        : (gwLast.ran === false ? '未运行'
        : (gwLast.mode === 'off' ? '关闭'
        : gwLast.external ? '外部护盾让位'
        : (gwLast.reason === 'off' ? '待命' : '本插件')))],
      ['模型锁', arActive ? ('见防路由 · ' + arLast.lock + ' 项')
        : (gwLast.lock > 0 ? '生效 · ' + gwLast.lock + ' 项'
        : (gwLast.ran === false ? '未运行'
          : (settings.gwLock === 'off' ? '关闭'
          : (gwLast.reason === 'off' ? '未触发'
            : (gwLast.lockSeen === 0 ? '不适用（无回退字段）' : '字段已是 false')))))],
      ['头部盐', arActive ? ('见防路由 · ' + arLast.added + ' 字')
        : (gwLast.salt > 0 ? '生效 · ' + gwLast.salt + ' 字'
        : (gwLast.ran === false ? '未运行'
          : (settings.gwSalt === 'off' ? '关闭' : '未触发')))],
      ['防截断加强', settings.rspStrongCut !== true ? '关'
        : (strongCutLast.applied ? '生效 · ' + (strongCutLast.native ? '原生' : 'OpenAI')
          : '开 · ' + (strongReason[strongCutLast.reason] || strongCutLast.reason || '未触发'))],
      ['网关额外字数', gwLast.added > 0 ? '+' + gwLast.added + ' 字' : '0'],
      ['最近结束原因', lastResp ? (lastResp.finish || (lastResp.errorObject ? '错误对象' : '未暴露')) : '未知'],
      ['最近思考字数', lastResp ? (lastResp.reasoning || 0) + ' 字' : '0'],
      ['最近空回分型', lastNet ? diagEmptyLabel(diagEmptyKind(lastNet)) : '未知'],
      ['响应拦截', rspState.enabled ? '生效'
        : rspState.installed ? '垫片中' : '未挂载'],
      ['最近格式', rspState.stats.lastFormat || '未识别'],
      ['已处理请求', rspState.stats.runs + ' 次'],
      ['还原命中', rspState.stats.hits + ' 次'],
      ['还原字符', rspState.stats.chars + ' 字'],
      ['断流次数', rspState.stats.cut + ' 次'],
      ['超长保护', rspState.stats.capped
        ? ('触发 ' + rspState.stats.capped + ' 次 · 单次上限 ' + RSP_CAP + ' 字')
        : ('未触发 · 单次上限 ' + RSP_CAP + ' 字')],
      ['最近截断形态', ({
        normal: '正常收尾',
        sentence: '句末附近',
        structure: '结构中间',
        'mid-text': '句子中间',
        'no-content': '没有内容',
        length: 'max_tokens 截断',
        filtered: '内容过滤',
        incomplete: '响应不完整'
      })[rspState.stats.lastCutKind] || '未记录']
    ];
  }

  function rspDiagText() {
    return '【拼音候选面板 · 增强诊断】\n版本：' + VERSION + '\n' +
      rspDiagRows().map(function (row) { return row[0] + '：' + row[1]; }).join('\n');
  }

  function rspDiagEventText(event) {
    const detail = Object.keys(event.detail || {}).map(function (key) {
      return key + '=' + event.detail[key];
    }).join(' ');
    return diagStamp(event.at) + ' · ' + event.type + (detail ? ' · ' + detail : '');
  }

  function rspDiagRoundText() {
    return rspDiagText() + '\n\n【最近事件（不含 URL / 密钥 / 正文）】\n' +
      (rspDiagEvents.length ? rspDiagEvents.map(rspDiagEventText).join('\n') : '暂无事件');
  }

  function diagNetLine(rec) {
    const q = rec.req || {};
    const bits = [diagClock(rec.at), rec.host || '未知主机'];
    if (q.model) bits.push('model=' + diagDecodeModel(q.model));
    if (q.stream === true) bits.push('stream');
    if (q.msgs) bits.push(q.msgs + ' 条消息');
    if (q.chars) bits.push(q.chars + ' 字');
    if (q.large) bits.push('正文 ' + q.large + ' 字节（未解析）');
    if (q.tools) bits.push(q.tools + ' 个工具');
    if (q.native) bits.push('原生形状');
    if (q.fallbackTop) bits.push('allow_fallbacks=' + q.fallbackTop);
    if (q.fallbackProvider) bits.push('provider.allow_fallbacks=' + q.fallbackProvider);
    if (q.salt) bits.push('请求盐 ' + q.salt + ' 枚');
    if (q.sysChars) bits.push('系统 ' + q.sysChars + ' 字');
    if (q.cot) bits.push('CoT 指令 ' + q.cot + ' 处');
    if (q.sysHash) bits.push('指纹 ' + q.sysHash);
    if (Array.isArray(q.shape) && q.shape.length) bits.push('非常规字段 ' + q.shape.join(','));
    if (Array.isArray(q.hdrOdd) && q.hdrOdd.length) bits.push('非常规头 ' + q.hdrOdd.join(','));
    if (q.maxTokens) bits.push('max_tokens=' + q.maxTokens);
    const head = bits.join(' · ');
    if (rec.error) return head + '\n    ✗ ' + diagRedact(arProbeRedact(String(rec.error))) + '（没有拿到 HTTP 响应）';
    if (!rec.resp) return head + '\n    … 已发出，未拿到响应';
    const r = rec.resp;
    const rb = ['HTTP ' + r.status];
    if (r.model) rb.push('响应 model=' + diagDecodeModel(r.model));
    if (r.finish) rb.push('finish=' + r.finish);
    if (r.blocked) rb.push('block=' + r.blocked);

    rb.push('首包 ' + ((r.ttfb || 0) / 1000).toFixed(2) + 's');
    rb.push('采样 ' + (r.peek || 0) + ' 字节' + (r.truncated ? '（截断）' : ''));
    if (r.len && r.len !== r.peek) rb.push('Content-Length ' + r.len);
    if (r.usage && (r.usage.prompt != null || r.usage.cacheHit != null || r.usage.cacheMiss != null)) {
      const u = r.usage;
      rb.push('tokens=' + (u.prompt == null ? '?' : u.prompt) +
        ' · cache hit=' + (u.cacheHit == null ? '?' : u.cacheHit) +
        ' miss=' + (u.cacheMiss == null ? '?' : u.cacheMiss));
    }
    if (rec.gw) {
      if (rec.gw.ran === false) rb.push('网关=未运行');
      else {
        rb.push('网关锁=' + (rec.gw.lock || 0) + ' 盐=' + (rec.gw.salt || 0) +
          (rec.gw.external ? ' 让位=' + rec.gw.external : ''));
      }
    }
    if (rec.obf) {
      rb.push('混淆=' + (rec.obf.mode || '?') + '/' + (rec.obf.carrier || '?') +
        ' 可读=' + (rec.obf.kept == null ? '?' : rec.obf.kept) + ' 段');
    }
    const empty = diagEmptyKind(rec);
    if (empty === 'http-error' || empty === 'error-object') {
      rb.push('异常=' + diagEmptyLabel(empty));
    } else if (empty === 'pending' || empty === 'sample-incomplete') {
      rb.push('采样=' + diagEmptyLabel(empty));
    } else if (empty !== 'none') {
      rb.push('空回=' + diagEmptyLabel(empty));
    }
    const hk = Object.keys(r.headers || {});
    if (hk.length) rb.push(hk.map(function (k) { return k + '=' + diagRedact(arProbeRedact(String(r.headers[k]))); }).join(' '));
    return head + '\n    → ' + rb.join(' · ');
  }

  function diagNetLines() {
    const list = Array.isArray(diagNetState.list) ? diagNetState.list : [];
    if (!list.length) {
      return ['本次运行没有捕获到生成请求（插件加载后还没发过消息）。'];
    }
    const out = [];
    for (let i = list.length - 1; i >= 0; i--) out.push(diagNetLine(list[i]));
    return out;
  }

  function diagModelCore(name) {
    let s = diagDecodeModel(name).trim().toLowerCase();

    s = s.replace(/^(?:gn|gw|global|route|router|proxy)[-:/]/, '');
    s = s.replace(/^[a-z0-9_.-]+\//, '');

    s = s.replace(/-\d{4}-\d{2}-\d{2}$/, '');
    s = s.replace(/-\d{8}$/, '');
    s = s.replace(/-\d{3,4}$/, '');
    return s;
  }

  function diagRouteVerdict(rec) {
    if (!rec) return { kind: 'none', text: '暂无请求' };
    if (rec.error) return { kind: 'error', text: '连接层失败' };
    const r = rec.resp || {};
    const q = rec.req || {};
    if (!rec.resp) return { kind: 'pending', text: '已发出，未拿到响应' };
    if (r.blocked || r.finish === 'content_filter') {
      return { kind: 'filtered', text: '上游内容过滤（不是改道）' };
    }
    if (r.status >= 400) return { kind: 'http-error', text: 'HTTP ' + r.status };
    if (r.errorObject) return { kind: 'error-object', text: 'HTTP 200 错误对象' };
    if (!rec.peekAt) return { kind: 'pending', text: '响应体还没采样完' };
    const reqModel = diagDecodeModel(q.model || '');
    const respModel = diagDecodeModel(r.model || '');
    if (!respModel) return { kind: 'unknown', text: '无法判断（响应未暴露 model / modelVersion）' };
    if (!reqModel) return { kind: 'unknown', text: '无法判断（请求模型未解析）' };
    if (reqModel === respModel) return { kind: 'same', text: '一致' };
    if (diagModelCore(reqModel) === diagModelCore(respModel)) {
      return { kind: 'alias', text: '别名差异（不是改道）' };
    }

    const light = /(?:flash[-_.]?lite|[-_.]lite\b|[-_.]mini\b|[-_.]nano\b|[-_.]small\b|[-_.]8b\b)/i;
    const downgrade = light.test(respModel) && !light.test(reqModel);
    return { kind: 'routed', text: '改道' + (downgrade ? '（疑似降级到轻量模型）' : '') };
  }

  function diagEmptyKind(rec) {
    if (!rec || !rec.resp) return 'none';
    const r = rec.resp;
    if (r.status >= 400) return 'http-error';
    if (r.truncated === true && r.contentSeen === false) return 'sample-incomplete';
    if (r.status === 200 && r.peek === 0) return rec.peekAt ? 'http-empty' : 'pending';
    if (r.errorObject) return 'error-object';
    if (r.finish === 'content_filter') return r.contentSeen ? 'none' : 'filtered';
    if (r.finish === 'length') {
      if (r.contentSeen) return 'none';
      return (r.reasoning > 0 && r.contentSeen === false) ? 'reasoning-length' : 'length';
    }
    if (r.reasoning > 0 && r.contentSeen === false) return 'reasoning-only';
    if (r.peek > 0 && r.contentSeen === false) return 'no-content';
    return 'none';
  }

  function diagEmptyLabel(kind) {
    if (kind === 'http-error') return 'HTTP 错误';
    if (kind === 'sample-incomplete') return '采样窗口内没看到正文（可能在后半段）';
    if (kind === 'pending') return '采样未完成';
    if (kind === 'http-empty') return 'HTTP 200 但响应体为空';
    if (kind === 'error-object') return 'HTTP 200 包装了错误对象';
    if (kind === 'filtered') return '被上游内容过滤';
    if (kind === 'length') return '被 max_tokens 截断';
    if (kind === 'reasoning-length') return '思考通道耗尽 max_tokens，正文为空';
    if (kind === 'reasoning-only') return '只有思考通道有内容，正文为空';
    if (kind === 'no-content') return '有响应体但没有正文';
    return '无';
  }

  function diagMaxTokensIgnored(rec) {
    try {
      const q = rec && rec.req || {};
      const r = rec && rec.resp || {};
      const mt = Number(q.maxTokens);
      if (!Number.isFinite(mt) || mt <= 0 || mt > 128) return false;
      const u = r.usage || {};
      const comp = Number(u.completion);
      if (Number.isFinite(comp) && comp > mt * 2) return true;
      if (r.contentSeen === true && r.finish === 'stop') {
        const chars = Number(r.contentChars) || 0;
        if (chars > mt * 8) return true;
      }
    } catch (e) {}
    return false;
  }
  function diagCause(rec) {
    if (!rec) return { label: '暂无请求', advice: '先发一条消息再导出' };
    const r = rec.resp || {};
    const q = rec.req || {};
    if (rec.error) return { label: '连接失败', advice: '检查网络、代理、渠道地址' };
    if (!rec.resp) return { label: '没拿到响应', advice: '请求可能被中断、超时或流没结束' };
    if (r.blocked || r.finish === 'content_filter') {
      return { label: '上游提示词/内容过滤', advice: '这是 Gemini/AI Studio 的过滤器，不是防路由或模型锁问题；先关防路由对比，再降低敏感内容或调整预设' };
    }
    if (r.status >= 400) return { label: 'HTTP ' + r.status, advice: '看错误体；鉴权/额度/模型名优先排查' };
    if (r.errorObject) return { label: '网关错误对象', advice: 'HTTP 200 包装了错误，按错误体处理' };
    const verdict = diagRouteVerdict(rec);
    if (verdict.kind === 'routed') {
      return { label: '上游改道', advice: '看模型锁/渠道；客户端无法强制上游不映射' };
    }
    if (r.finish === 'length') return { label: '输出预算不足', advice: '调大 max_tokens，或缩短输入' };
    if ((r.reasoning || 0) > 0 && r.contentSeen === false) {
      return { label: '思考占满 / 正文没出来', advice: '调大 max_tokens；检查是否只开了思考通道' };
    }
    if (r.status === 200 && rec.peekAt && r.contentSeen === false && r.sawDone === true) {
      return { label: '预设正则吞字 / 正文被删空', advice: '检查预设正则；先关回包修复对比' };
    }
    if (r.status === 200 && rec.peekAt && r.contentSeen === false && !r.sawDone) {
      return { label: '流未完成 / 网络中断', advice: '重发一次；检查代理是否切断流' };
    }
    if (r.status === 200 && !r.peek) return { label: '响应体为空', advice: '检查上游是否空回，或采样未完成' };
    if (!String(q.model || '')) return { label: '请求模型未解析', advice: '看请求形状是否被网关改写' };
    if (diagMaxTokensIgnored(rec)) {
      return { label: '上游忽略 max_tokens / 抗截断代理接管', advice: '不要用 max_tokens 限制长度；以 finish 与正文为准，防截断由上游处理' };
    }
    return { label: '未发现异常', advice: '这轮没有明显问题' };
  }
  function diagCauseText(rec) {
    const c = diagCause(rec);
    return c.label + ' · ' + c.advice;
  }
  function arProbeCompareText() {
    const list = Array.isArray(arProbeHistory) ? arProbeHistory : [];
    if (!list.length) return '暂无探针历史';
    const map = {};
    list.forEach(function (h) {
      if (!h) return;
      const key = String(h.base || '未知渠道') + ' | ' + String(h.reqModel || '?');
      const x = map[key] || (map[key] = { n: 0, same: 0, alias: 0, routed: 0, err: 0, ms: 0 });
      x.n++;
      if (h.kind === 'same') x.same++;
      else if (h.kind === 'alias') x.alias++;
      else if (h.kind === 'routed') x.routed++;
      if (h.status === 'error' || h.error) x.err++;
      if (typeof h.ms === 'number') x.ms += h.ms;
    });
    const rows = Object.keys(map).map(function (k) {
      const x = map[k];
      return k + '：' + x.n + ' 次 · 一致 ' + x.same + ' / 别名 ' + x.alias +
        ' / 改道 ' + x.routed + ' / 失败 ' + x.err +
        (x.n ? ' · 均 ' + Math.round(x.ms / x.n) + 'ms' : '');
    });
    return rows.slice(0, 6).join('；');
  }
  function diagRouteAdvice(rec, verdict) {
    const out = [];
    const q = (rec && rec.req) || {};
    const r = (rec && rec.resp) || {};
    const gw = (rec && rec.gw) || {};
    const arOn = settings.arEnabled === true && String(settings.arProfile || 'auto') !== 'off';
    if (gw.ran === false && !arOn) out.push('本次网关层没有运行：检查网关开关 / 是否被外部护盾让位');
    if (gw.ran === false && arOn) out.push('本次由防路由接管：检查防路由档位 / 模型锁 / 头部盐是否生效');
    if (verdict.kind === 'routed') {
      if (gw.ran !== false && !gw.lock && settings.gwLock !== 'off') {
        if (gw.lockSeen === 0) {
          if (q.fallbackTop || q.fallbackProvider || q.fallbackOpenRouter || q.fallbackUse) {
            out.push('请求里有回退字段，但本次模型锁没有运行；检查网关开关或外部让位');
          } else {
            out.push('请求里没有可锁的回退字段；模型锁对这一渠道不适用，换渠道或看上游路由');
          }
        } else {
          out.push(gw.provider === 'other'
            ? '请求里有可锁的回退字段，但当前模式没覆盖这个渠道；可改成「有回退字段就锁」'
            : '先开模型锁，锁死回退字段');
        }
      }
      if (!gw.salt && settings.gwSalt !== 'off') out.push('模型锁已开仍改道：开头部盐，排除模板缓存路由');
      if (gw.lock > 0 && gw.salt > 0) out.push('锁和盐都生效仍改道：上游有强制路由/模型映射，换渠道或看响应头');
      if (q.fallbackTop === 'true' || q.fallbackProvider === 'true') out.push('请求里的回退字段仍是 true');
    } else if (verdict.kind === 'same') {
      if (q.fallbackTop === 'true' || q.fallbackProvider === 'true') {
        out.push('模型一致，但回退字段仍开着，下一轮可能被切走');
      }
      if (r.usage && r.usage.cacheHit > 0 && !gw.salt) {
        out.push('前缀缓存命中；若怀疑缓存池路由，可开头部盐');
      }
    } else if (verdict.kind === 'unknown') {
      out.push('换一个会回传 model / modelVersion 的渠道，或看响应头 x-model / x-route');
    }
    if (r.finish === 'length') out.push('同时被 max_tokens 截断：提高 max_tokens');
    if (r.reasoning > 0 && r.contentSeen === false) {
      out.push('正文为空但思考有内容：提高 max_tokens 或关闭思考');
    }
    const empty = diagEmptyKind(rec);
    if (empty === 'sample-incomplete') out.push('响应超过 64KB 采样窗口，正文可能在后面；重新导出或查看完整响应');
    if (empty === 'http-empty') out.push('上游返回空响应：检查渠道或网关');
    if (empty === 'pending') out.push('响应体还没采样完：稍后重新导出');
    if (empty === 'filtered') out.push('被上游内容过滤：换渠道或调整预设');
    if (empty === 'error-object') out.push('网关用 HTTP 200 包装了错误：看错误对象与渠道配置');
    if (empty === 'no-content') out.push('有响应体但没有正文：检查预设正则是否把内容删空');
    return out.length ? out.join('；') : '暂不需要调整';
  }

  function diagRouteRows() {
    const list = Array.isArray(diagNetState.list) ? diagNetState.list : [];
    const last = list.length ? list[list.length - 1] : null;
    if (!last) {
      return [['状态', '本次没有捕获到生成请求'], ['建议', '先发一条消息再导出']];
    }
    const q = last.req || {};
    const r = last.resp || {};
    const reqModelText = diagDecodeModel(q.model || '');
    const respModelText = diagDecodeModel(r.model || '');
    const gw = last.gw || null;
    const u = r.usage || {};
    const headers = r.headers || {};
    const routeHeaders = Object.keys(headers)
      .filter(function (k) { return /^x-(?:model|route|provider|upstream|backend)$/i.test(k); })
      .map(function (k) { return k + '=' + headers[k]; }).join(' ') || '无';
    const verdict = diagRouteVerdict(last);
    const routed = list.filter(function (rec) { return diagRouteVerdict(rec).kind === 'routed'; }).length;
    const empties = list.filter(function (rec) {
      const kind = diagEmptyKind(rec);
      return kind === 'http-empty' || kind === 'filtered' ||
        kind === 'reasoning-only' || kind === 'reasoning-length' ||
        kind === 'no-content' || kind === 'length';
    }).length;
    const errors = list.filter(function (rec) {
      if (rec.error) return true;
      const kind = diagEmptyKind(rec);
      return kind === 'http-error' || kind === 'error-object';
    }).length;
    const samples = list.filter(function (rec) {
      return diagEmptyKind(rec) === 'sample-incomplete';
    }).length;
    return [
      ['统计范围', '最近 ' + list.length + ' 条请求'],
      ['本次请求', list.length + ' 次'],
      ['本次改道', routed + ' 次'],
      ['本次空回', empties + ' 次'],
      ['本次错误', errors + ' 次'],
      ['本次采样未完成', samples + ' 次'],
      ['请求模型', reqModelText || '未知'],
      ['响应模型', respModelText || '未知'],
      ['核心名', (diagModelCore(reqModelText) || '?') + ' → ' + (diagModelCore(respModelText) || '?')],
      ['判定', verdict.text],
      ['最可能原因', diagCauseText(last)],
      ['系统提示', (q.sysChars || 0) + ' 字 · ' + (q.sysParas || 0) + ' 段 · 指纹 ' + (q.sysHash || '?')],
      ['思维链指令', q.cot
        ? (q.cot + ' 处' + ((q.cotLines && q.cotLines.length)
          ? '（行 ' + q.cotLines.map(function (x) { return x.line; }).join(' / ') + '）' : ''))
        : '未发现'],
      ['盐覆盖', '头 ' + (q.saltHead || 0) + ' / 中 ' + (q.saltMid || 0) + ' / 尾 ' + (q.saltTail || 0) +
        ' · ' + (settings.arSaltStable === true ? '本页面内固定' : '每轮随机')],
      ['请求形状', (q.shape && q.shape.length) ? ('非常规字段：' + q.shape.join(' / ')) : '未发现非常规字段'],
      ['请求头', (q.hdrOdd && q.hdrOdd.length) ? ('非常见头：' + q.hdrOdd.join(' / ')) : '未发现非常见头'],
      ['探针对照', arProbeCompareText()],
      ['网关层', gw ? (gw.ran === false
        ? ((settings.arEnabled === true && String(settings.arProfile || 'auto') !== 'off') ? '由防路由接管' : '未运行（网关关闭 / 未装配）')
        : (gw.external ? '外部护盾让位（' + gw.external + '）'
          : (gw.reason === 'off' ? '待命 / 关闭' : '本插件'))) : '未记录'],
      ['模型锁', gw ? (gw.ran === false
        ? ((settings.arEnabled === true && String(settings.arProfile || 'auto') !== 'off') ? '见防路由' : '未运行')
        : (gw.lock > 0 ? '生效 · ' + gw.lock + ' 项'
        : (gw.lockSeen === 0
          ? ((q.fallbackTop || q.fallbackProvider || q.fallbackOpenRouter || q.fallbackUse)
            ? '未运行（请求里有回退字段）' : '不适用（无回退字段）')
          : '字段已是 false'))) : '未记录'],
      ['头部盐', gw ? (gw.ran === false
        ? ((settings.arEnabled === true && String(settings.arProfile || 'auto') !== 'off') ? '见防路由' : '未运行')
        : (gw.salt > 0 ? '生效 · ' + gw.salt + ' 字' : '未生效')) : '未记录'],
      ['回退字段', [q.fallbackTop ? 'allow_fallbacks=' + q.fallbackTop : '',
        q.fallbackProvider ? 'provider.allow_fallbacks=' + q.fallbackProvider : '',
        q.fallbackOpenRouter ? 'openrouter_allow_fallbacks=' + q.fallbackOpenRouter : '',
        q.fallbackUse ? 'openrouter_use_fallback=' + q.fallbackUse : '']
        .filter(Boolean).join(' · ') || '未出现'],
      ['请求盐', q.salt ? q.salt + ' 枚' : '无'],
      ['输出上限', diagMaxTokensIgnored(last)
        ? ('疑似被上游忽略（请求 ' + q.maxTokens + '，实际完成 ' + ((u.completion == null) ? '?' : u.completion) + ' tokens，finish=' + (r.finish || '?') + '）')
        : (q.maxTokens ? ('请求 max_tokens=' + q.maxTokens) : '未设置')],
      ['前缀缓存', (u.cacheHit == null && u.prompt == null) ? '未暴露'
        : ('hit=' + (u.cacheHit == null ? '?' : u.cacheHit) +
          ' miss=' + (u.cacheMiss == null ? '?' : u.cacheMiss) +
          ' prompt=' + (u.prompt == null ? '?' : u.prompt))],
      ['响应路由头', routeHeaders],
      ['结束原因', r.finish || (r.errorObject ? '错误对象' : '未暴露')],
      ['空回分型', diagEmptyLabel(diagEmptyKind(last))],
      ['建议', diagRouteAdvice(last, verdict)]
    ];
  }

  function diagRouteTrail() {
    const list = Array.isArray(diagNetState.list) ? diagNetState.list : [];
    if (!list.length) return '暂无请求';
    return list.slice(-5).map(function (rec) {
      const q = rec.req || {};
      const r = rec.resp || {};
      const gw = rec.gw || {};
      const u = r.usage || {};
      const gwText = gw.ran === false ? '网关未运行'
        : '锁' + (gw.lock || 0) + '/盐' + (gw.salt || 0);
      return diagClock(rec.at) + ' · ' + (diagDecodeModel(q.model) || '?') + ' → ' + (diagDecodeModel(r.model) || '?') +
        ' · ' + diagRouteVerdict(rec).text +
        ' · cache=' + (u.cacheHit == null ? '?' : u.cacheHit) +
        ' · ' + gwText;
    }).join('\n');
  }

  function diagNetVerdicts() {
    const out = [];
    const list = Array.isArray(diagNetState.list) ? diagNetState.list : [];
    if (!list.length) {
      out.push('⚠ 没有捕获到生成请求：本次运行没发过消息，或请求没走到 fetch');
      return out;
    }
    const last = list[list.length - 1];
    if (last.error) {
      out.push('⚠ 最近一次请求在连接层失败：' + last.error);
    } else if (!last.resp) {
      out.push('⚠ 最近一次请求已发出，但没有拿到响应（若生成仍在进行，忽略此条）');
    } else {
      const r = last.resp;
      const reqModel = (last.req && last.req.model) || '';
      if (r.status >= 400) {
        out.push('⚠ 最近一次请求：HTTP ' + r.status + '（被网关或后端拒绝，不是模型不回）');
      } else if (!r.model) {
        out.push(!last.peekAt
          ? '✅ 最近一次请求：HTTP ' + r.status + ' 返回（响应体还没采样完，稍后重新导出）'
          : '✅ 最近一次请求：HTTP ' + r.status +
            ' 返回（响应未暴露 model，无法据此判断是否被改道）');
      } else if (!reqModel) {
        out.push('✅ 最近一次请求：HTTP ' + r.status + ' · 响应 model=' + r.model +
          '（请求体未解析，无法比对）');
      } else if (reqModel === r.model) {
        out.push('✅ 最近一次请求：HTTP ' + r.status +
          ' · 模型一致（上游换供应商无法从 model 字段判断）');
      } else if (diagModelCore(reqModel) === diagModelCore(r.model)) {
        out.push('✅ 最近一次请求：模型名只是别名差异（' + reqModel + ' → ' + r.model +
          '），不是改道');
      } else {
        out.push('⚠ 最近一次请求：模型被改道 ' + reqModel + ' → ' + r.model +
          '（核心模型名不同，这一条就是「是否被路由」的答案）');
        out.push('  建议：' + diagRouteAdvice(last, { kind: 'routed' }));
      }
      if (r.status === 200 && r.peek === 0) out.push('⚠ HTTP 200 但响应体为空');
      if (r.status === 200 && r.errorObject) out.push('⚠ HTTP 200 但响应体是错误对象（网关用 200 包装了错误）');
      if (r.status === 200 && r.reasoning > 0 && r.contentSeen === false) {
        out.push(r.truncated
          ? '⚠ 采样窗口内只看到思考，正文可能在 64KB 之后；请重新导出或查看完整响应'
          : '⚠ 正文为空，但思考通道有 ' + r.reasoning + ' 字：可能是 max_tokens 不足，或模型把答案写进了思考');
      }
      if (r.finish === 'length') out.push('⚠ 最近一次回复被 max_tokens 截断（finish=length）');
      if (r.finish === 'content_filter') out.push('⚠ 最近一次回复被上游内容过滤（finish=content_filter）');
    }
    const lost = list.filter(function (r) {
      return r !== last && !r.resp && !r.error;
    }).length;
    if (lost) out.push('⚠ 本次捕获的 ' + list.length + ' 次请求里，有 ' + lost + ' 次只发出、没拿到响应');
    return out;
  }

  function diagFeatureLine(label, on, key) {
    if (!on) return label + '：关';
    const st = diagFeatureState[key];
    if (!st) return label + '：开 · 本次还没触发';
    return label + '：开 · ' + diagClock(st.at) + ' ' +
      (st.ok ? '正常' : '没结果') + (st.detail ? '（' + st.detail + '）' : '');
  }

  function diagFeatureLines() {
    const inputSt = diagFeatureState['输入框'];
    const genSt = diagFeatureState['生成方式'];
    const rows = [
      '输入框：' + (inputSt
        ? '已绑定 · ' + diagClock(inputSt.at) + ' 收到输入（' + inputSt.detail + '）'
        : (genSt && /重新生成|续写/.test(genSt.detail)
          ? '本次没收到输入（' + genSt.detail + ' 不经过输入框，属正常）'
          : '本次还没收到输入')),
      '生成方式：' + (genSt ? genSt.detail : '本次还没生成'),
      diagFeatureLine('候选面板', settings.masterEnabled === true, '候选面板'),
      diagFeatureLine('拼音', settings.masterEnabled === true && settings.rowPinyin === true, '拼音'),
      diagFeatureLine('谐音', settings.masterEnabled === true && settings.rowHarmonic === true, '谐音'),
      diagFeatureLine('融合', settings.masterEnabled === true && settings.rowFusion === true, '融合'),
      diagFeatureLine('混语', settings.masterEnabled === true && settings.mixEnabled === true, '混语'),
      diagFeatureLine('编码', settings.masterEnabled === true && rowEncodeOn(), '编码'),
      diagFeatureLine('英文', settings.masterEnabled === true && rowEnglishOn(), '英文'),
      diagFeatureLine('注音', settings.masterEnabled === true && rowBopoOn(), '注音'),
      diagFeatureLine('空耳', settings.masterEnabled === true && rowKongerOn(), '空耳'),
      diagFeatureLine('组合', settings.masterEnabled === true && settings.comboEnabled === true, '组合'),
      diagFeatureLine('一键转化', settings.oneKeyEnabled === true, '一键转化'),
      diagFeatureLine('混淆', obfRequestEnabled(), '混淆'),
      diagFeatureLine('炼狱', settings.hellEnabled === true, '炼狱'),
      diagFeatureLine('回应增强', settings.rspEnabled === true, '回应增强'),
      '网关层：' + (gwLast.ran === false ? '未运行'
        : (settings.gwMode === 'off' ? '关'
        : (gwLast.reason === 'off' ? '开 · 本次还没触发'
          : '开 · 锁' + gwLast.lock + ' / 盐' + gwLast.salt +
            (gwLast.external ? ' / 让位=' + gwLast.external : ''))))
    ];
    if (obfCompatState.runs) rows.push('数据库兼容：已放行 ' + obfCompatState.runs + ' 次结构化消息');
    return rows;
  }

  function diagFeatureWarnings() {
    const out = [];
    const st = diagFeatureState;
    const rows = ['拼音', '融合', '编码', '注音', '空耳'];
    for (let i = 0; i < rows.length; i++) {
      const r = st[rows[i]];
      if (r && !r.ok && /失败|加载|未命中/.test(r.detail)) {
        out.push('⚠ ' + rows[i] + '最近一次没出结果（' + r.detail + '）');
      }
    }
    if (diagNetState.list.length && obfRequestEnabled() && !st['混淆']) {
      out.push('⚠ 最近有请求，但本次运行没有记录到任何混淆动作');
    }
    if (diagNetState.list.length && settings.hellEnabled === true && !st['炼狱']) {
      out.push('⚠ 炼狱开着，但最近这次请求没有记录到炼狱套层');
    }
    return out;
  }

  function pluginDiagText() {
    try {
    const onOff = function (v) { return v === true ? '开' : '关'; };
    const rows = [
      ['主开关', onOff(settings.masterEnabled)],
      ['拼音候选', onOff(settings.rowPinyin)],
      ['谐音候选', onOff(settings.rowHarmonic)],
      ['英文候选', onOff(rowEnglishOn())],
      ['英文方案', englishModeLabel(settings.enMode)],
      ['融合候选', onOff(settings.rowFusion)],
      ['一键转化', onOff(settings.oneKeyEnabled)],
      ['请求混淆', onOff(settings.obfEnabled)],
      ['炼狱模式', onOff(settings.hellEnabled)],
      ['数据库兼容', onOff(settings.plotCompat)],
      ['结构化放行', obfCompatState.runs + ' 次'],
      ['混淆体检', obfRouteState.runs
        ? obfRouteState.runs + ' 段检查 · ' + obfRouteState.kept + ' 段仍可读 · ' +
          (obfRouteState.mode || '?') + ' / ' + (obfRouteState.carrier || '?')
        : (diagShared.lastObf ? '无可测样本（原文没有连续 3 个汉字）' : '本次未记录')],
      ['回应增强', onOff(settings.rspEnabled)]
    ];
    const storage = diagStorage();
    const verdicts = diagNetVerdicts()
      .concat(diagFeatureWarnings())
      .concat(diagFindings(storage).map(function (s) { return '⚠ ' + s; }));
    const warns = verdicts.filter(function (v) { return v.indexOf('⚠') === 0; }).length;
    return diagRedact(arProbeRedact('【拼音候选面板 · 整体诊断】\n版本：' + VERSION + '\n' +
      '生成时间：' + diagStamp(Date.now()) + '（本地）\n' +
      '说明：本报告只记形状不记正文；判断不了的地方会直接写「无法判断」。\n' +
      '\n【结论】\n自动判断：' + (warns ? '发现 ' + warns + ' 个值得看的问题' : '未发现明显异常') + '\n' +
      verdicts.map(function (v) { return '  ' + v; }).join('\n') +
      '\n\n【路由诊断】\n' +
      diagRouteRows().map(function (row) { return row[0] + '：' + row[1]; }).join('\n') +
      '\n\n【最近模型轨迹】\n' + diagRouteTrail() +
      '\n\n【最近请求（不含正文）】\n' + diagNetLines().join('\n') +
      '\n\n【功能体检】\n' + diagFeatureLines().join('\n') +
      '\n\n【配置】\n' +
      rows.map(function (row) { return row[0] + '：' + row[1]; }).join('\n') +
      '\n\n【运行环境（不含正文 / URL / 密钥）】\n' + diagRuntimeLines().join('\n') +
      '\n\n' + rspDiagRoundText()));
    } catch (e) {
      return '【拼音候选面板 · 整体诊断】\n版本：' + VERSION + '\n' +
        '诊断生成失败：' + diagRedact(String(e && e.message || e)) + '\n' +
        '建议：重新加载页面后再试；若仍失败，说明共享诊断数据的形状异常。\n' +
        '说明：本报告不含正文 / URL / 密钥。';
    }
  }

  function diagRuntimeLines() {
    const lines = [];
    const plat = diagPlatform();
    const storage = diagStorage();
    lines.push('平台：' + plat.where + ' · ' + plat.view + ' · 宿主 ' + plat.host);
    lines.push('宿主版本：' + (diagTTVersion || '未知（宿主未暴露）'));
    lines.push('本地存储：' + storage);
    let ballText = '未知';
    try {
      ballText = (tbtn && tbtn.isConnected && host.getComputedStyle(tbtn).display !== 'none')
        ? '显示' : '隐藏';
    } catch (e) {}
    lines.push('悬浮球：' + ballText);
    let rescueText = '缺失';
    try { rescueText = pdoc.getElementById(RESCUE_ID) ? '已挂' : '缺失'; } catch (e) {}
    lines.push('备用入口：' + rescueText);
    lines.push('当前场景：' + diagSceneLabel(sceneActiveId()) +
      ' · 设置面板' + (settingsOpen ? '打开' : '关闭'));
    const ev = Object.keys(diagEventCount)
      .sort(function (a, b) { return diagEventCount[b].n - diagEventCount[a].n; })
      .slice(0, 8)
      .map(function (k) { return k + ' ' + diagEventCount[k].n; });
    lines.push('事件计数：' + (ev.length ? ev.join(' · ') : '本次运行还没触发'));
    const sendSide = [];
    if (settings.hellEnabled === true) sendSide.push('炼狱');
    if (settings.obfEnabled === true && settings.hellEnabled !== true) sendSide.push('混淆');
    if (settings.oneKeyEnabled === true) sendSide.push('一键转化');
    if (settings.rspEnabled === true) sendSide.push('回应增强');
    lines.push('发送侧改写：' + (sendSide.length ? sendSide.join(' + ') : '无（插件不改动发送内容）'));
    if (diagShared.lastObf) {
      const lastObf = diagShared.lastObf;
      lines.push(lastObf.plotSafe
        ? '最近混淆：数据库兼容放行（结构化消息未改写）'
        : ('最近混淆：' + lastObf.mode + ' / ' + lastObf.carrier +
          ' · 输入 ' + lastObf.inLen + ' 字 → 输出 ' + lastObf.outLen + ' 字' +
          (lastObf.runs
            ? ' · ' + lastObf.runs + ' 段检查 / ' + lastObf.kept + ' 段仍可读'
            : ' · 无可测样本（原文没有连续 3 个汉字）')));
      const residue = diagCarrierResidue();
      if (residue >= 0) {
        lines.push('上下文回查：' + (residue
          ? '⚠ 有 ' + residue + ' 条历史消息仍是载体（生成中属临时态；生成结束还在就是没还原）'
          : '历史消息无本轮载体残留（载体只存在于当前这一份请求）'));
      }
    }
    const ownErrN = diagErrors.filter(function (e) { return e.kind !== 'host'; }).length;
    lines.push('JS 错误：' + (diagErrors.length
      ? diagErrors.length + ' 条' +
        (ownErrN < diagErrors.length ? '（其中宿主运行时 ' + (diagErrors.length - ownErrN) + ' 条）' : '')
      : '无'));
    for (let i = 0; i < diagErrors.length; i++) {
      const e = diagErrors[i];
      lines.push('  · ' + diagClock(e.at) + ' [' + e.kind + ']' +
        (e.kind === 'host' ? '（非插件）' : '') + ' ' + e.msg);
    }
    if (diagActions.length) {
      lines.push('最近操作（最多 40 条）：');
      for (let i = Math.max(0, diagActions.length - 20); i < diagActions.length; i++) {
        const a = diagActions[i];
        lines.push('  ' + diagClock(a.at) + ' ' + a.label +
          (a.detail ? ' ' + a.detail : ''));
      }
    }
    lines.push('说明：本报告不含正文 / URL / 密钥；时间均为本地时间。');
    return lines;
  }

  function diagSceneLabel(id) {
    const key = String(id || '');
    if (!key) return '自定义';
    try {
      for (let i = 0; i < RSP_SCENES.length; i++) {
        if (RSP_SCENES[i] && RSP_SCENES[i].id === key) return RSP_SCENES[i].label;
      }
    } catch (e) {}
    return key;
  }

  function diagFindings(storage) {
    const out = [];
    try {
      if (!tbtn || !tbtn.isConnected) out.push('悬浮球不在 DOM 里');
      if (!pdoc.getElementById(RESCUE_ID)) out.push('备用入口未挂上（没找到酒馆魔法棒菜单）');
      if (storage !== '正常') out.push('本地存储写入失败：设置改了也存不住');
      if (settings.hellEnabled === true && settings.plotCompat !== true) {
        const shape = diagLastRequestShape();
        const structured = !!(shape && (shape.plotDirective === true ||
          shape.recallBlocks || shape.supplementBlocks || shape.cbBlocks));
        out.push(structured
          ? '炼狱开 / 数据库兼容关：本次请求含结构化块，可能已被混淆'
          : '炼狱开 / 数据库兼容关：本次请求没有结构化块，暂无影响（用到数据库/剧情推进时需打开兼容）');
      }
      if (settings.oneKeyEnabled === true) {
        out.push('一键转化开启：输入框内容会被改写后再发送（数据库兼容只对结构化消息例外）');
      }
      if (obfRequestEnabled() && (!obfBindDiag || !obfBindDiag.bound)) {
        out.push('混淆事件没绑上（eventOn 不可用），发送时不会有任何混淆');
      }
      if (settings.rspEnabled === true && rspState.installed === true && rspState.enabled !== true) {
        out.push('回应增强已开但拦截处于「垫片」状态');
      }
      if (dirtyOrFailedSave) out.push('设置落盘失败（' + dirtyOrFailedSave + '）');
      if (diagErrors.some(function (e) { return e.kind !== 'host'; })) {
        out.push('运行期有插件 JS 错误，见下方明细');
      }
      try {
        const list = Array.isArray(diagNetState.list) ? diagNetState.list : [];
        const last = list.length ? list[list.length - 1] : null;
        if (last && last.resp && last.resp.blocked) {
          out.push('最近一次请求被上游提示词过滤（block=' + last.resp.blocked + '），这不是防路由/模型锁导致');
        }
      } catch (e) {}
    } catch (e) {}
    return out;
  }

  function diagLastRequestShape() {
    try {
      for (let i = rspDiagEvents.length - 1; i >= 0; i--) {
        if (rspDiagEvents[i] && rspDiagEvents[i].type === 'request') return rspDiagEvents[i].detail;
      }
    } catch (e) {}
    return null;
  }

  function diagCarrierResidue() {
    const last = diagShared.lastObf;
    if (!last) return -1;
    if (last.plotSafe) return 0;
    if (!last.probe) return -1;
    try {
      const arr = obfChat();
      if (!Array.isArray(arr)) return -1;
      let hit = 0;
      for (let i = 0; i < arr.length; i++) {
        const m = arr[i];
        if (m && typeof m.mes === 'string' && m.mes.indexOf(last.probe) >= 0) hit++;
      }
      return hit;
    } catch (e) { return -1; }
  }

  function rspRenderStats() {
    let el = null;
    try { el = settingsEl && settingsEl.querySelector('[data-rsp-stats]'); } catch (e) {}
    const s = rspState.stats;
    const text = !rspOn()
      ? '未启用'
      : '已处理 ' + s.runs + ' 次请求 · 还原 ' + s.hits + ' 次 · 共 ' + s.chars + ' 字' +
        (s.cut ? ' · 断流 ' + s.cut + ' 次' : '') +
        (s.capped ? ' · 超长保护 ' + s.capped + ' 次' : '') +
        (s.lastFormat ? ' · 格式 ' + s.lastFormat : '') +
        (rspState.enabled ? ' · 拦截生效'
          : rspState.installed ? ' · 已关闭（包装垫片中，不再处理回应）'
          : ' · 未挂载（找不到可拦截的 fetch）');
    if (el) el.textContent = text;
    let qel = null;
    try { qel = settingsEl && settingsEl.querySelector('[data-rsp-quick-last]'); } catch (e) {}
    if (qel) {
      qel.textContent = !rspOn()
        ? '回包修复已关闭'
        : (s.hits ? '已还原 ' + s.hits + ' 次 · 处理 ' + s.runs + ' 次' : '回包修复已开启，等下一次回复');
    }
    let sel = null;
    try { sel = settingsEl && settingsEl.querySelector('[data-rsp-quick-state]'); } catch (e) {}
    if (sel) {
      sel.textContent = !rspOn() ? '已关闭'
        : (rspState.enabled ? '已开启' : (rspState.installed ? '已开启 · 垫片' : '已开启 · 未挂载'));
    }
    if (!el) return;

    let diagEl = null;
    try { diagEl = settingsEl && settingsEl.querySelector('[data-rsp-diag]'); } catch (e) {}
    if (!diagEl) return;
    if (!rspOn()) {
      diagEl.innerHTML = '<div class="thp-hint-line">未启用；打开「响应侧 · 回包修复」后才有运行数据。</div>';
      let ev0 = null;
      try { ev0 = settingsEl && settingsEl.querySelector('[data-rsp-events]'); } catch (e) {}
      if (ev0) ev0.innerHTML = '';
      return;
    }
    diagEl.innerHTML = rspDiagRows().map(function (row) {
      return '<div class="thp-diag-item"><span class="thp-diag-k">' + escapeHtml(row[0]) +
        '</span><span class="thp-diag-v">' + escapeHtml(String(row[1])) + '</span></div>';
    }).join('');

    let eventsEl = null;
    try { eventsEl = settingsEl && settingsEl.querySelector('[data-rsp-events]'); } catch (e) {}
    if (!eventsEl) return;
    eventsEl.innerHTML = rspDiagEvents.slice(-10).map(function (event) {
      return '<div class="thp-diag-event">' + escapeHtml(rspDiagEventText(event)) + '</div>';
    }).join('');
  }

