  function flowComboData(id) {
    const key = String(id || '');
    for (let i = 0; i < FLOW_COMBOS.length; i++) {
      if (FLOW_COMBOS[i].id === key) return FLOW_COMBOS[i];
    }
    return null;
  }

  function flowCurrentCombo() {
    if (settings.masterEnabled !== true) return '';
    if (settings.hellEnabled === true) return 'conv-obf-hell';
    if (settings.obfEnabled === true) return 'conv-obf';
    return 'conv';
  }

  function flowComboLabel(id) {
    const C = flowComboData(id);
    return C ? C.label : '未配置';
  }

  function flowArOn() {
    return settings.arEnabled === true && String(settings.arProfile || 'auto') !== 'off';
  }

  function flowRspOn() {
    return settings.rspEnabled === true;
  }

  function flowSetModules(obf, hell) {
    settings.masterEnabled = true;
    if (hell === true) {
      settings.hellEnabled = true;
      settings.obfEnabled = false;
      settings.obfHellPrevObfEnabled = obf === true;
    } else {
      settings.hellEnabled = false;
      settings.obfEnabled = obf === true;
      settings.obfHellPrevObfEnabled = null;
    }
  }

  function arRenderEasyCards() {
    try {
      if (!settingsEl) return;
      const active = flowCurrentCombo();
      settingsEl.querySelectorAll('[data-flow-combo]').forEach(function (el) {
        const on = el.getAttribute('data-flow-combo') === active;
        el.classList.toggle('thp-on', on);
        el.setAttribute('aria-pressed', on ? 'true' : 'false');
        const choose = el.querySelector('.thp-easy-choose');
        if (choose) choose.textContent = on ? '正在使用' : '用这套 ›';
      });
    } catch (e) {}
  }

  function arRenderEasySummary() {
    try {
      if (!settingsEl) return;
      const el = settingsEl.querySelector('[data-easy-summary]');
      if (!el) return;
      const arOn = flowArOn();
      const rspOn = flowRspOn();
      const hellOn = settings.hellEnabled === true;
      const convOn = settings.masterEnabled === true;
      const obfOn = settings.obfEnabled === true && !hellOn;
      const chips = [
        { id: 'conv', name: '转换', value: convOn ? '开' : '关', on: convOn, jump: 'conv', sec: 'convpreset' },
        { id: 'obf', name: '混淆', value: hellOn ? '交给炼狱' : (obfOn ? '开' : '关'), on: obfOn, jump: 'obf', sec: '' },
        { id: 'hell', name: '炼狱', value: hellOn ? '开' : '关', on: hellOn, jump: 'hell', sec: '' },
        { id: 'ar', name: '防路由', value: arOn ? '开' : '关', on: arOn, jump: 'route', sec: '' },
        { id: 'rsp', name: '回包修复', value: rspOn ? '开' : '关', on: rspOn, jump: 'route', sec: '' }
      ];
      el.innerHTML = chips.map(function (c) {
        return '<button class="thp-easy-chip thp-easy-chip--link' + (c.on ? ' thp-on' : '') +
          '" type="button" data-jump="' + c.jump + '"' +
          (c.sec ? ' data-jump-sec="' + c.sec + '"' : '') +
          '><i>' + escapeHtml(c.name) + '</i><b>' + escapeHtml(c.value) + '</b></button>';
      }).join('');

      settingsEl.querySelectorAll('[data-flow-state]').forEach(function (st) {
        const id = st.getAttribute('data-flow-state');
        const on = id === 'ar' ? arOn : rspOn;
        st.textContent = on ? '已开启' : '已关闭';
        st.classList.toggle('thp-on', on);
      });
      settingsEl.querySelectorAll('[data-flow-toggle]').forEach(function (btn) {
        const id = btn.getAttribute('data-flow-toggle');
        const on = id === 'ar' ? arOn : rspOn;
        btn.textContent = on ? '关闭' : '开启';
        btn.classList.toggle('thp-btn-primary', !on);
      });
      const rawArOn = settings.arEnabled === true;
      const arProf = String(settings.arProfile || 'auto');
      const activeProf = (!rawArOn || arProf === 'off') ? 'off' : arProf;
      settingsEl.querySelectorAll('[data-ar-quick-profile]').forEach(function (btn) {
        const on = btn.getAttribute('data-ar-quick-profile') === activeProf;
        btn.classList.toggle('thp-on', on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      });
    } catch (e) {}
  }

  function arRenderEasyStatus() {
