      if (!settingsEl) return;
      const el = settingsEl.querySelector('[data-ar-easy-status]');
      if (!el) return;
      const main = flowCurrentCombo();
      const extras = [];
      if (flowArOn()) extras.push('防路由');
      if (flowRspOn()) extras.push('回包修复');
      el.textContent = '主流程：' + flowComboLabel(main) +
        (extras.length ? ' · 另开：' + extras.join(' / ') : '');
