    const C = flowComboData(id);
    if (!C) return false;
    flowSetModules(C.obf, C.hell);
    settings.arEasyCase = id;
    try { obfCarrierCache = null; } catch (e) {}
    saveSettings();
    try { flushSettings(); } catch (e) {}
    try { hellSyncControls(); } catch (e) {}
    try { obfSyncScopes(); } catch (e) {}
    try { obfPreviewRender(); } catch (e) {}
    try { convSyncPresets(); } catch (e) {}
    try { quickRenderPreview(); } catch (e) {}
    try { syncSettingsControls(); } catch (e) {}
    try { rspRenderScenes(); } catch (e) {}
    try { arRenderEasyCards(); } catch (e) {}
    try { arRenderEasySummary(); } catch (e) {}
    try { arRenderEasyStatus(); } catch (e) {}
    try { if (host.toastr) host.toastr.success('主流程已切换：' + C.label); } catch (e) {}
    return true;
  }

  function flowToggleAdv(id) {
    let on = false;
    if (id === 'ar') {
      on = !flowArOn();
      settings.arEnabled = on;
      if (on && String(settings.arProfile || 'auto') === 'off') settings.arProfile = 'auto';
    } else if (id === 'rsp') {
      on = !(settings.rspEnabled === true);
      settings.rspEnabled = on;
      if (!on) settings.rspScene = '';
    } else {
      return false;
    }
    settings.arEasyCase = '';
    saveSettings();
    try { flushSettings(); } catch (e) {}
    try { rspSync(); } catch (e) {}
    try { syncSettingsControls(); } catch (e) {}
    try { rspRenderScenes(); } catch (e) {}
    try { arRenderStats(); } catch (e) {}
    try { rspRenderStats(); } catch (e) {}
    try { arRenderEasyCards(); } catch (e) {}
    try { arRenderEasySummary(); } catch (e) {}
    try { arRenderEasyStatus(); } catch (e) {}
    try { if (host.toastr) host.toastr.success((id === 'ar' ? '防路由' : '回包修复') + (on ? '已开启' : '已关闭')); } catch (e) {}
    return true;
  }

