        blockLeft = 1 + ((rng() * 3) | 0);
      }

      if (blockKind === 'ec') {
        const scheme = schemeAt(bumps.combo);
        let chunk = '';
        let taken = 0;
        while (taken < blockLeft && i + taken < value.length && CJK_TEST.test(value[i + taken])) {
          chunk += value[i + taken];
          taken++;
        }
        if (!chunk) { out += ch; blockLeft--; i++; continue; }
        const token = encodeText(chunk, scheme);
        if (prevKind === 'py' || prevKind === 'latin' || prevKind === 'ec') out += ' ';
        out += token + ' ';
        prevKind = 'ec';
        blockLeft -= taken;
        prevHit = false;
        i += taken;
        continue;
      }

      if (blockKind === 'bp' || blockKind === 'kg') {
        const conv = blockKind === 'bp' ? bopomofoSyllable : kongerSyllable;

        const sepOn = blockKind === 'bp' ? (settings.bopoSep !== false) : (settings.kongerSep !== false);
        let taken = 0;
        let piece = '';
        if (blockKind === 'kg') {
          let plen = 0, pout = '';
          for (let len = Math.min(KONGER_PHRASE_MAX, value.length - i, blockLeft); len >= 2; len--) {
            const w = value.substr(i, len);
            if (KONGER_PHRASE[w]) { plen = len; pout = KONGER_PHRASE[w]; break; }
          }
          if (plen) {
            if (prevKind && prevKind !== 'other') out += ' ';
            out += (sepOn ? pout : pout.replace(/ /g, '')) + ' ';
            prevKind = 'other';
            blockLeft -= plen;
            i += plen;
            prevHit = false;
            continue;
          }
        }
        while (taken < blockLeft && i + taken < value.length && CJK_TEST.test(value.charAt(i + taken))) {
          const syl = conv(value.charAt(i + taken)) || value.charAt(i + taken);
          piece += (piece && sepOn ? ' ' : '') + syl;
          taken++;
        }
        if (!taken) { out += ch; blockLeft--; i++; continue; }
        if (prevKind && prevKind !== 'other') out += ' ';
        out += piece + ' ';
        prevKind = 'other';
        blockLeft -= taken;
        prevHit = false;
        i += taken;
        continue;
      }

      if (blockKind === 'ox') {
        out += ch;
        prevKind = 'other';
        prevHit = false;
        blockLeft--;
        i++; continue;
      }

      if (blockKind === 'mx') {
        const lang = langs.length > 1 ? langs[(rng() * langs.length) | 0] : langs[0];
        const dict = MIX_DICTS[lang];
        let hit = null;
        for (let len = Math.min(4, value.length - i); len >= 1; len--) {
          const w = value.substr(i, len);
          if (dict[w] !== undefined) { hit = { en: dict[w], len: len }; break; }
        }
        if (hit && rng() < mixRatio) {
          if (hit.en) {
            if (prevKind === 'py' || prevKind === 'latin') out += ' ';
            out += hit.en + ' ';
          }
          prevKind = 'other';
          blockLeft -= hit.len;
          prevHit = false;
          i += hit.len; continue;
        }
        out += ch;
        prevKind = 'other';
        blockLeft--;
        prevHit = false;
        i++; continue;
      }
      if (blockKind === 'py') {
        const py = pinyinCharOf(ch);
        if (py) {
          if (prevKind === 'latin') out += ' ';
          else if (prevKind === 'py') out += settings.sep;
          out += py;
          prevKind = 'py';
          blockLeft--;
          prevHit = false;
          i++; continue;
        }
      }

      if (settings.hbSmart && (FUNC_KEEP.indexOf(ch) >= 0 || mask[i] || prevHit)) {
        out += ch; prevKind = 'other'; prevHit = false; i++; continue;
      }
      if (rng() > prob) { out += ch; prevKind = 'other'; prevHit = false; i++; continue; }
      const rep = pickHomophone(ch, readings ? readings[i] : null, rng) || ch;
      out += rep;
      prevKind = 'other';
      prevHit = rep !== ch;
      blockLeft--;
      i++;
    }

    return normalizeTapBoundary(out).replace(/ +([，。！？；、：）】」”…])/g, '$1')
      .replace(/ {2,}/g, ' ').replace(/ +$/, '');
  }

