  function rulesToText(dict) {
    const d = normalizeCustomMap(dict);
    const lines = [];
    Object.keys(d).forEach(function (k) {
      const items = d[k].items;
      items.forEach(function (it, i) {

        lines.push((i === 0 ? k + '=' : '') + it.mode + (it.target !== '' ? '=' + it.target : ''));
      });
    });
    return lines.join('\n');
  }

  function textToRules(text) {
    const map = Object.create(null);
    let lastKey = '';
    for (const raw of String(text || '').split('\n')) {
      const line = raw.trim();
      if (!line || line.charAt(0) === '#') continue;
      const i = line.indexOf('=');
      let k = '', rest = '';
      if (i <= 0) {

        if (!lastKey) continue;
        rest = line;
        k = lastKey;
      } else {
        k = line.slice(0, i).trim();
        rest = line.slice(i + 1);
      }
      const j = rest.indexOf('=');
      const mode = (j >= 0 ? rest.slice(0, j) : rest).trim();
      const target = j >= 0 ? rest.slice(j + 1).trim() : '';
      if (!k || RULE_MODE_IDS.indexOf(mode) < 0) continue;
      lastKey = k;
      if (!map[k]) map[k] = { items: [], prefer: 0 };
      map[k].items.push({ mode: mode, target: target });
    }
    return map;
  }

