  function renderComboSum() {
    const el = settingsEl.querySelector('.thp-combo-sum');
    if (!el) return;

    const w = comboWeights();
    const langs = w.langs;
    const total = w.py + w.hb + w.mx + w.ox + w.en + w.bo + w.ko;
    if (total <= 0) {
      el.innerHTML = '当前各路占比都是 <b>0</b> —— 「合」行不会产出内容（调高任一路即可）。';
      return;
    }
    const pct = function (v) { return Math.round(v * 100 / total); };
    const items = [
      ['拼音', w.py], ['谐音', w.hb], ['外语词', w.mx], ['原文字', w.ox],
      ['编码', w.en], ['注音', w.bo], ['空耳', w.ko]
    ];

    const sum = items.reduce(function (a, x) { return a + pct(x[1]); }, 0);
    let tailAt = 0;
    for (let i = 1; i < items.length; i++) if (items[i][1] > items[tailAt][1]) tailAt = i;
    const parts = items.map(function (x, i) {
      const v = pct(x[1]) + (i === tailAt ? 100 - sum : 0);
      return x[0] + ' <b>' + v + '%</b>';
    });
    el.innerHTML = '实际混合比例：' + parts.join(' · ') +
      (langs.length ? '（外语词：' + langs.map(function (L) { return L.label; }).join(' / ') + ' 交替出现）'
        : '（未勾选任何外语 → 外语词那一路暂不生效）');
  }

  function comboOf(e) {
    const parts = [];
    if (e.ctrlKey) parts.push('Ctrl');
    if (e.metaKey) parts.push('Meta');
    if (e.altKey) parts.push('Alt');
    if (e.shiftKey) parts.push('Shift');
    const code = e.code || '';
    if (!code) return null;
    const ok = /^(Key[A-Z]|Digit\d)$/.test(code) || code === 'Space' || code === 'Enter' ||
      code === 'Tab' || code === 'Escape' || code === 'Backspace' ||
      /^Arrow(Up|Down|Left|Right)$/.test(code) || /^F([1-9]|1[0-2])$/.test(code);
    if (!ok) return null;
    parts.push(code);
    return parts.join('+');
  }

