  function placeSettings() {
    if (sDragging) return;
    const vw = host.innerWidth;

    let vh = host.innerHeight;
    try {
      const vv = host.visualViewport;
      if (vv && vv.height && vv.height < vh) vh = vv.height;
    } catch (e) {}
    let w = Math.min(560, Math.round(vw * 0.94));
    settingsEl.classList.toggle('thp-narrow', w < 420);

    let avoid = null;
    let avoidStack = null;
    try {
      settingsEl.style.maxHeight = '';

      if (vw < 560) {
        w = Math.min(w, vw - 16);
        settingsEl.style.width = w + 'px';
      }

      const cpEl = pdoc.getElementById(PANEL_ID);
      if (cpEl && cpEl.classList && cpEl.classList.contains('thp-show') && cpEl.offsetWidth) {
        const pr = cpEl.getBoundingClientRect();
        avoid = { left: pr.left, right: pr.right, top: pr.top, bottom: pr.bottom };

        if (!settings.settingsOffset) {
        const gap = 12;
        const rightRoom = vw - pr.right - gap - 8;
        const leftRoom = pr.left - gap - 8;
        const best = Math.max(rightRoom, leftRoom);

        const roomSide = Math.max(vw - (pr.right + gap) - 8, (pr.left - gap) - 8);
        if (roomSide >= 380) {
          w = Math.min(w, roomSide);
          settingsEl.classList.toggle('thp-narrow', w < 420);
        } else {
          settingsEl.classList.remove('thp-narrow');
          w = Math.min(w, vw - 16);
          const gapY = 10;
          const belowRoom = vh - (pr.bottom + gapY) - 8;
          const aboveRoom = pr.top - gapY - 4;

          const minStack = vw < 560 ? 220 : 420;
          if (belowRoom >= minStack && belowRoom >= aboveRoom) {
            avoidStack = { top: pr.bottom + gapY, maxH: belowRoom };
          } else if (aboveRoom >= minStack) {
            avoidStack = { topAbove: pr.top - gapY, maxH: aboveRoom };
          }
        }
        }
      }
    } catch (e) {}
    settingsEl.style.width = w + 'px';
    settingsEl.classList.toggle('thp-narrow', w < 420);

    if (vh < host.innerHeight - 8) {
      settingsEl.style.maxHeight = Math.max(220, vh - 16) + 'px';
    }
    if (settingsOpen) {
      try { settingsEl.offsetHeight; } catch (e) {}
    }
    const sh = Math.min(settingsEl.offsetHeight || 420, vh * 0.8);

    let left = (vw - w) / 2;
    let top = (vh - sh) / 2 - vh * 0.03;

    try {
      const cpEl2 = pdoc.getElementById(PANEL_ID);
      if (avoid && cpEl2) {
        const cpl = cpEl2.getBoundingClientRect().left;
        if (cpl + cpEl2.offsetWidth / 2 > vw / 2) left = 8;
        else left = vw - w - 8;
      }
    } catch (e) {}
    const off = settings.settingsOffset;
    if (off) {
      left += off.dx || 0;
      top += off.dy || 0;
    }

    try {

      if (avoid && !off) {
        const pr = avoid;
        const gap = 12;
        const overlap = !(left + w <= pr.left || left >= pr.right || top + sh <= pr.top || top >= pr.bottom);
        if (overlap) {
          if (vw - (pr.right + gap) - 8 >= w) left = pr.right + gap;
          else if ((pr.left - gap) - 8 >= w) left = pr.left - gap - w;
          else if (avoidStack) {

            settingsEl.style.maxHeight = avoidStack.maxH + 'px';
            if (typeof avoidStack.top === 'number') top = avoidStack.top;
            else top = Math.max(8, avoidStack.topAbove - avoidStack.maxH);
          }
        }
      }
    } catch (e) {}
    settingsEl.style.left = clampN(left, 8, Math.max(8, vw - w - 8)) + 'px';
    settingsEl.style.top = clampN(top, 8, Math.max(8, vh - 40)) + 'px';
  }

