  jq(settingsEl).on('click' + NS, '.thp-help summary', function (e) {
    e.preventDefault();
    const d = this.closest('.thp-help');
    const willOpen = !d.hasAttribute('open');
    closeSettingsHelp(d);
    if (willOpen) {
      d.setAttribute('open', '');

      host.requestAnimationFrame(function () {
        try {
          const pop = d.querySelector('.thp-help-pop');
          const scroller = settingsEl.querySelector('.thp-st-body') || settingsEl;
          if (!pop || !scroller) return;
          const sr = scroller.getBoundingClientRect();
          const pr = pop.getBoundingClientRect();

          const tabs = settingsEl.querySelector('.thp-tabs');
          let topLimit = sr.top;
          if (tabs) {
            const tb = tabs.getBoundingClientRect().bottom;
            if (tb > topLimit && tb < sr.bottom) topLimit = tb;
