    }
    const mw = menuEl.offsetWidth || 150;
    const mh = menuEl.offsetHeight || 84;

    const GAP = 10;
    const cx = tr.left + (tr.width || 0) / 2;
    const rightRoom = host.innerWidth - tr.right;
    const leftRoom = tr.left;

    let side = rightRoom >= leftRoom ? 'right' : 'left';
    if (side === 'right' && rightRoom < mw + GAP + 8 && leftRoom > rightRoom) side = 'left';
    if (side === 'left' && leftRoom < mw + GAP + 8 && rightRoom > leftRoom) side = 'right';
    let left = side === 'right' ? tr.right + GAP : tr.left - mw - GAP;
    left = clampN(left, 8, Math.max(8, host.innerWidth - mw - 8));

