  function saveWithHostDialog(text, filename) {
    const invoke = ttInvoke();
    if (!invoke) return Promise.resolve('unsupported');
    let stagedPath = '';
    return Promise.resolve().then(function () {
      const bytes = new TextEncoder().encode(text);
      return invoke('stage_file_begin', {
        dto: { kind: 'export', preferred_extension: 'txt', size: bytes.length }
      }).then(function (begin) {
        stagedPath = String((begin && begin.file_path) || '');
        if (!stagedPath) throw new Error('staging unavailable');
        const chunkSize = Math.max(1, Number(begin.chunk_size) || bytes.length);
        let offset = 0;
        const step = function () {
          if (offset >= bytes.length) return Promise.resolve();
          const end = Math.min(offset + chunkSize, bytes.length);
          return invoke('stage_file_chunk', bytes.slice(offset, end), {
            headers: { 'file-path': encodeURIComponent(stagedPath), offset: String(offset) }
          }).then(function (next) {
            if (Number(next) !== end) throw new Error('staging offset mismatch');
            offset = end;
            return step();
          });
        };
        return step().then(function () {
          return invoke('stage_file_finish', { filePath: stagedPath, expectedSize: bytes.length });
        }).then(function () {
          return invoke('deliver_staged_file', { path: stagedPath, fileName: filename });
        }).then(function (res) {
          stagedPath = '';
          return res && res.delivered === false ? 'cancelled' : 'saved';
        });
      });
    }).catch(function () {
      if (stagedPath) {
        try { invoke('stage_file_discard', { filePath: stagedPath }); } catch (e) {}
      }
      return 'unsupported';
    });
  }

