    }).filter(function (it) { return RULE_MODE_IDS.indexOf(it.mode) >= 0; });
    if (!items.length) return null;
    const star = card.querySelector('.thp-ci-pref.thp-on');
    const prefer = star ? Number(star.closest('.thp-ci-row').getAttribute('data-idx')) || 0 : 0;
    return { key: k, entry: { items: items, prefer: prefer } };
  }

  function customCardValid(card) {
    const got = readCustomCard(card);
    if (!got) return false;
    return got.entry.items.every(function (it) {

      return it.mode !== 'replace' || it.target !== '';
    });
  }
  function saveCustomCard(card) {
    if (!customCardValid(card)) return false;
    const got = readCustomCard(card);
    const map = normalizeCustomMap(settings.customLibrary);
    const oldKey = card.getAttribute('data-k');
    if (oldKey && oldKey !== got.key) delete map[oldKey];
    map[got.key] = got.entry;
    settings.customLibrary = map;

    if (oldKey === '') ruleTab = got.entry.items[0].mode;
    card.removeAttribute('data-draft');
    saveSettings();
    renderWordsGrid();
    rerender();
    return true;
  }

  function wordsSaveRow(row) {
    const src = (row.querySelector('.thp-wg-src').value || '').trim();
    const mode = row.querySelector('.thp-wg-mode').value;
    const target = (row.querySelector('.thp-wg-target').value || '').trim();
    if (!src) return;
    const rules = normalizeRuleMap(settings.customLibrary);
    const k0 = row.getAttribute('data-k');
    if (k0 && k0 !== src) delete rules[k0];
    rules[src] = { mode: mode, target: target };
    settings.customLibrary = rules;
    ruleTab = mode;
    saveSettings();
    renderWordsGrid();
    rerender();
  }
  function ruleRowMarkDraft(row, draft) {
    if (!row) return;
    row.classList.toggle('thp-wg-placeholder', !!draft);
    row.classList.toggle('thp-wg-new', !!draft);
    if (draft) {
      row.setAttribute('data-new', '1');
      row.setAttribute('data-placeholder', '1');
    } else {
      row.removeAttribute('data-new');
      row.removeAttribute('data-placeholder');
    }
  }
  function ruleRowCommit(row, save) {
    const src = (row.querySelector('.thp-wg-src').value || '').trim();
    if (!src) {
      row.querySelector('.thp-wg-src').focus();
      return false;
    }
    const mode = row.querySelector('.thp-wg-mode').value;
    const target = (row.querySelector('.thp-wg-target').value || '').trim();
    if (mode === 'replace' && !target) {
      row.querySelector('.thp-wg-target').focus();
      return false;
    }
    row.setAttribute('data-k', src);
    ruleRowMarkDraft(row, false);
    save(row);
    return true;
  }

