  let cuBump = 0;
  function cuPreviewRender() {
    const out = settingsEl.querySelector('.thp-cu-out');
    const input = settingsEl.querySelector('.thp-cu-in');
    if (!out || !input) return;
    const src = (input.value || '').trim();
    if (!src) { out.innerHTML = '<div class="thp-cu-empty">输入文本后点「试转」</div>'; return; }
    const keep = bumps.custom;
    bumps.custom = cuBump;
    let text = '';
    try { text = convertCustomValue(src) || ''; } finally { bumps.custom = keep; }
    out.innerHTML = text
      ? '<div class="thp-cu-row"><span class="thp-rc-tag thp-rc-custom">自</span>' +
        '<span class="thp-cu-text">' + escapeHtml(text) + '</span></div>'
      : '<div class="thp-cu-empty">未命中词条 —— 先在上面添加词条</div>';
  }
  jq(settingsEl).on('click' + NS, '[data-act="cu-preview"]', cuPreviewRender);
  jq(settingsEl).on('click' + NS, '[data-act="cu-regen"]', function () {
    cuBump++;
    cuPreviewRender();
  });
  jq(settingsEl).on('input' + NS, '[data-sec="words"] .thp-cu-in', function () {
    cuBump = 0;
    cuPreviewRender();
  });

  function contSyncScopes() {
    if (!settingsEl) return;
    settingsEl.querySelectorAll('[data-sec="ak"] [data-ak-scope]').forEach(function (el) {
      if (el.getAttribute('data-ak-scope') === 'convert') el.hidden = !settings.akProcConvert;
    });
  }

  function contMatchPreset() {
    for (let i = 0; i < CONT_PRESETS.length; i++) {
      const cfg = CONT_PRESETS[i].cfg;
      let hit = true;
      for (const k of Object.keys(cfg)) {
        if (String(settings[k]) !== String(cfg[k])) { hit = false; break; }
      }
      if (hit) return CONT_PRESETS[i];
    }
    return null;
  }
  function contSyncPresets() {
    if (!settingsEl) return;
    const cur = contMatchPreset();
    syncPresetChips('[data-ak-preset]', 'data-ak-preset', cur);
    const sec = settingsEl.querySelector('[data-sec="ak"]');
    const label = sec && sec.querySelector('.thp-ak-cur');
    if (label) label.textContent = cur ? ' · 当前：' + cur.label : ' · 当前：自定义';
  }
  function contApplyPreset(id) {
    const P = CONT_PRESETS.filter(function (x) { return x.id === id; })[0];
    if (!P) return;
    Object.keys(P.cfg).forEach(function (k) { settings[k] = P.cfg[k]; });
    saveSettings();
    syncSettingsControls();
    contSyncScopes();
    contSyncPresets();
    if (host.toastr) host.toastr.success('已套用续写档位「' + P.label + '」');
  }

  function obfSyncScopes() {
    const mode = settings.obfMode;
    settingsEl.querySelectorAll('[data-obf-scope]').forEach(function (el) {
      const scope = el.getAttribute('data-obf-scope');
      let show = false;
      if (scope === 'custom') show = settings.obfBracket === 'custom';
      else if (scope === 'sep') show = mode === 'template' || mode === 'wrap';
    else if (scope === 'scatter') show = mode === 'scatter';
      else if (scope === 'layered') show = mode === 'layered';
      else if (scope === 'hell') show = mode === 'hell';
      else if (scope === 'template') show = mode === 'template';
      el.hidden = !show;
    });

    const tpl = settingsEl.querySelector('.thp-obf-tpl');
    if (tpl) tpl.hidden = mode !== 'template';
    obfSyncPresets();
    obfSyncCarrierEditor();
    obfSyncRandomNote();
  }

  function obfMatchPreset() {
    for (let i = 0; i < OBF_PRESETS.length; i++) {
      const cfg = OBF_PRESETS[i].cfg;
      let hit = true;
      for (const k of Object.keys(cfg)) {
        if (String(settings[k]) !== String(cfg[k])) { hit = false; break; }
      }
      if (hit) return OBF_PRESETS[i];
    }
    return null;
  }
  function obfSyncPresets() {
    const cur = obfMatchPreset();
    settingsEl.querySelectorAll('[data-obf-carrier]').forEach(function (b) {
      const active = b.getAttribute('data-obf-carrier') === settings.obfCarrier;
      b.classList.toggle('thp-on', active);
