      b.setAttribute('aria-pressed', active ? 'true' : 'false');
    });

    const sec = settingsEl.querySelector('[data-sec="obf"]');
    const label = sec && sec.querySelector('.thp-obf-cur');
    if (label) {
      label.textContent = settings.hellEnabled
        ? (' · 休眠：' + (cur ? cur.label : '自定义'))
