    const quickLabel = settingsEl.querySelector('[data-sec="quick"] .thp-quick-obf-current');
    if (quickLabel) quickLabel.textContent = settings.hellEnabled ? '炼狱接管中' : (cur ? cur.label : '自定义');
    const first = sec && sec.querySelector('.thp-obf-first');
    if (first) {
      first.textContent = settings.obfSkipFirstUser === true
        ? '已保护本聊天的第一条用户输入：开局设定、变量规则和 HTML 面板不会被混淆。'
        : '提示：第一条用户输入当前也会参与混淆；如需保护开局设定，可打开「首条用户输入不参与」。';
