  function syncPresetChips(sel, attr, cur) {
    settingsEl.querySelectorAll(sel).forEach(function (b) {
      const id = b.getAttribute(attr);
      const on = id === CUSTOM_PRESET_ID ? !cur : (!!cur && id === cur.id);
      b.classList.toggle('thp-on', on);
    });
  }
  function convMatchPreset() {
    const activeType = String(settings.convType || '');
    for (let i = 0; i < CONV_PRESETS.length; i++) {
      if (activeType && CONV_PRESETS[i].type !== activeType) continue;
      const cfg = CONV_PRESETS[i].cfg;
      let hit = true;
      for (const k of Object.keys(cfg)) {
        if (String(settings[k]) !== String(cfg[k])) { hit = false; break; }
      }
      if (hit) return CONV_PRESETS[i];
    }
    return null;
  }
  function convSyncPresets() {
    const cur = convMatchPreset();
    const activeType = (cur && cur.type) || String(settings.convType || '');
    settingsEl.querySelectorAll('[data-conv-type]').forEach(function (b) {
      const active = !!activeType && b.getAttribute('data-conv-type') === activeType;
      b.classList.toggle('thp-on', active);
      b.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
    settingsEl.querySelectorAll('[data-conv-level]').forEach(function (b) {
      const lv = b.getAttribute('data-conv-level');
      const blendOnly = b.getAttribute('data-blend-only') === '1';

      b.disabled = blendOnly && !!activeType && activeType !== 'blend';
      const active = !!cur && cur.level === lv;
      b.classList.toggle('thp-on', active);
      b.setAttribute('aria-pressed', active ? 'true' : 'false');
    });

    const sec = settingsEl.querySelector('[data-sec="convpreset"]');
    const label = sec && sec.querySelector('.thp-conv-cur');
    if (label) label.textContent = cur ? ' · 当前：' + cur.label : ' · 当前：自定义';
    const quickLabel = settingsEl.querySelector('[data-sec="quick"] .thp-quick-conv-current');
    if (quickLabel) quickLabel.textContent = cur ? cur.label : '自定义';
  }
  function convApplyPreset(id) {
    const P = CONV_PRESETS.filter(function (x) { return x.id === id; })[0];
    if (!P) return;
    settings.convType = P.type;
    bumps.english = 0;
    Object.keys(P.cfg).forEach(function (k) {
      if (CONV_PRESET_KEYS.indexOf(k) < 0) return;
      settings[k] = P.cfg[k];
    });
    saveSettings();
    syncSettingsControls();
    update();
    if (host.toastr) host.toastr.success('已套用转换档位「' + P.label + '」');
  }

  function convApplyType(type) {
    const cur = convMatchPreset();
    const keep = cur && cur.level &&
      CONV_PRESETS.some(function (p) { return p.id === type + '-' + cur.level; })
      ? cur.level : 'mid';
    const P = CONV_PRESETS.filter(function (p) { return p.id === type + '-' + keep; })[0] ||
      CONV_PRESETS.filter(function (p) { return p.id === 'blend-' + keep; })[0];
    if (P) convApplyPreset(P.id);
  }
  function convApplyLevel(level) {
    const cur = convMatchPreset();
    const type = (cur && cur.type) || settings.convType || 'blend';
    const P = CONV_PRESETS.filter(function (p) { return p.id === type + '-' + level; })[0] ||
      CONV_PRESETS.filter(function (p) { return p.id === 'blend-' + level; })[0];
    if (P) convApplyPreset(P.id);
  }
  function obfApplyPreset(id) {
    const P = OBF_PRESETS.filter(function (x) { return x.id === id; })[0];
    if (!P) return;
    Object.keys(P.cfg).forEach(function (k) {
      if (OBF_PRESET_KEYS.indexOf(k) < 0) return;
      settings[k] = P.cfg[k];
    });

    settings.hellEnabled = false;
    settings.obfHellPrevObfEnabled = null;
    settings.obfEnabled = true;
    saveSettings();
    syncSettingsControls();
    obfPreviewRender();
