  function obfSyncCarrierEditor() {
    const box = settingsEl.querySelector('.thp-obf-carrier-box');
    if (!box) return;

    const c = obfCarrierForEditor();
    const t = box.querySelector('.thp-obf-carrier');
    const m = box.querySelector('.thp-obf-marker');
    if (t && t !== pdoc.activeElement) t.value = c.text;
    if (m && m !== pdoc.activeElement) m.value = c.marker;
  }

  function obfCarrierForEditor() {
    const base = OBF_CARRIERS.filter(function (c) { return c.id === settings.obfCarrier; })[0] || OBF_CARRIERS[0];
    const ov = obfOverride(base.id);
    const custom = (typeof ov.text === 'string' && ov.text.trim()) ? ov.text : '';
    const marker = obfNormMarker(typeof ov.marker === 'string' ? ov.marker : base.marker, base.marker);
    return { id: base.id, label: base.label, marker: marker, text: custom || base.text };
  }

  function obfCommitCarrier() {
    const box = settingsEl.querySelector('.thp-obf-carrier-box');
    if (!box) return;
    const id = settings.obfCarrier;
    const base = OBF_CARRIERS.filter(function (c) { return c.id === id; })[0] || OBF_CARRIERS[0];
    const text = box.querySelector('.thp-obf-carrier').value;
    const markerEl = box.querySelector('.thp-obf-marker');
    const typed = markerEl ? markerEl.value : '';
    const marker = obfNormMarker(typed, base.marker);

    if (markerEl && typed !== marker) markerEl.value = marker;
    if (!settings.obfSets || typeof settings.obfSets !== 'object') settings.obfSets = {};
    if (text === base.text && marker === base.marker) delete settings.obfSets[id];
    else settings.obfSets[id] = { text: text, marker: marker };
    saveSettings();
    obfSyncRandomNote();
  }

  function obfSyncRandomNote() {
    const cb = settingsEl.querySelector('#th-pinyin-ime-settings input[data-set="obfRandomCarrier"]');
    if (!cb) return;
    const base = OBF_CARRIERS.filter(function (c) { return c.id === settings.obfCarrier; })[0] || OBF_CARRIERS[0];
    const ov = obfOverride(base.id);
    const hasCustom = !!(ov.text && String(ov.text).trim());
    cb.disabled = hasCustom;
    const label = cb.closest('label');
