        : '开启后每轮现生成一份形态相同、细节全变的载体，避免多轮重复同一段文本被模型学会跳过';
      label.style.opacity = hasCustom ? '0.55' : '';
      let note = label.querySelector('.thp-obf-randnote');
      if (hasCustom && !note) {
        note = pdoc.createElement('span');
        note.className = 'thp-obf-randnote';
