  function autoRulesSorted() {
    const rules = wbRulesValid();
    return Object.keys(rules).sort(function (a, b) { return b.length - a.length; })
      .map(function (k) { return { k: k, mode: rules[k].mode, target: rules[k].target }; });
  }

  function convertOneKey(text, mode) {
    if (!text) return '';
    const rules = autoRulesSorted();
    const defaultFn = function (part) {
      if (!part) return part;
      try { return withRuleBypass(function () { return oneKeyConvertPhrase(part, mode); }); }
      catch (e) { return part; }
    };
    if (!rules.length) return defaultFn(text) || text;
    let out = '', pending = '', i = 0;
    while (i < text.length) {
      let hit = null;
      for (let r = 0; r < rules.length; r++) {
        if (text.startsWith(rules[r].k, i)) { hit = rules[r]; break; }
      }
      if (!hit) { pending += text[i]; i++; continue; }
      if (pending) { out += defaultFn(pending); pending = ''; }
      const conv = autoConvertPhrase(hit.k, hit);
      out += (conv != null && conv !== '') ? conv : hit.k;
      i += hit.k.length;
    }
    if (pending) out += defaultFn(pending);
    return out;
  }
  function oneKeyConvertPhrase(phrase, mode) {
    if (mode === 'keep') return phrase;
    if (mode === 'pinyin') return convertPinyinValueBase(phrase);
    if (mode === 'harmonic') return convertHarmonicValueBase(phrase);
    if (mode === 'fusion') return convertFusionValueBase(phrase);
    if (mode === 'mix') return convertMixValueBase(phrase, true);
    if (mode === 'encode') return convertEncodeValueBase(phrase);
    if (mode === 'traditional') return convertTraditionalValueBase(phrase);
    if (mode === 'classical') return convertClassicalValueBase(phrase);
    if (mode === 'bopo') return convertBopomofoValueBase(phrase);
    if (mode === 'konger') return convertKongerValueBase(phrase);
    if (mode === 'english') return convertEnglishValue(phrase, settings.enMode);
    if (mode === 'combo') return convertComboValueBase(phrase);
    return phrase;
  }
  function autoConvertPhrase(phrase, rule) {
    if (rule.target !== '') return rule.target;
    const mode = rule.mode;
    try {
      return withRuleBypass(function () {
        if (mode === 'keep') return phrase;
        if (mode === 'replace') return phrase;
        if (mode === 'pinyin') return convertPinyinValueBase(phrase);
        if (mode === 'harmonic') {
          const keepSmart = settings.hbSmart, keepProb = settings.hbProb;
          if (keepSmart) settings.hbSmart = false;
          settings.hbProb = 100;
          const r = convertHarmonicValueBase(phrase);
          settings.hbSmart = keepSmart;
          settings.hbProb = keepProb;
          return r;
        }
        if (mode === 'fusion') {
          const keepSmart = settings.hbSmart, keepProb = settings.hbProb, keepFusion = settings.fusionProb;
          settings.hbSmart = false;
          settings.hbProb = 100;
          settings.fusionProb = 100;
          const r = convertFusionValueBase(phrase);
          settings.hbSmart = keepSmart;
          settings.hbProb = keepProb;
          settings.fusionProb = keepFusion;
          return r;
        }
        if (mode === 'mix') return convertMixValueBase(phrase, true);
        if (mode === 'encode') return convertEncodeValueBase(phrase);
        if (mode === 'traditional') return convertTraditionalValueBase(phrase);
        if (mode === 'classical') return convertClassicalValueBase(phrase);
        if (mode === 'bopo') return convertBopomofoValueBase(phrase);
        if (mode === 'konger') return convertKongerValueBase(phrase);
        if (mode === 'english') return convertEnglishValue(phrase, settings.enMode);
        if (mode === 'combo') return convertComboValueBase(phrase);
      });
    } catch (e) { return null; }
  }

  function autoConvertPass(text) {
    const rules = autoRulesSorted();
    if (!rules.length || !text) return null;
    const memo = {};
    let out = '', i = 0, hits = 0;
    while (i < text.length) {
      let hit = null;
      for (let r = 0; r < rules.length; r++) {
        if (text.startsWith(rules[r].k, i)) { hit = rules[r]; break; }
      }
      if (hit) {
        if (!(hit.k in memo)) memo[hit.k] = autoConvertPhrase(hit.k, hit);
        const conv = memo[hit.k];
        out += (conv != null && conv !== '' && conv !== hit.k) ? conv : hit.k;
        i += hit.k.length;
        hits++;
      } else { out += text[i]; i++; }
    }
    return hits ? out : null;
  }

  let autoTimer = 0;
