  function maybeAutoConvert() {
    if (!autoSilent(ta) || !ta || ta !== mainTa) return;
    if (composing || editApplying) { scheduleAutoConvert(); return; }
    const current = String(ta.value || '');
    let v = current;
    const lastOut = autoOutputs.get(ta);
    if (typeof lastOut === 'string') {
      if (current === lastOut) {
        v = autoSources.get(ta) || current;
      } else if (current.length > lastOut.length && current.slice(0, lastOut.length) === lastOut) {
        v = (autoSources.get(ta) || lastOut) + current.slice(lastOut.length);
