      const base = Math.max(0, ids.indexOf(settings.oneKeyMode));
      mode = ids[(base + (bumps.oneKey || 0)) % ids.length];
      bumps.oneKey = (bumps.oneKey || 0) + 1;
    }
    const out = settings.oneKeyEnabled
      ? convertOneKey(v, mode)
      : autoConvertPass(v);
    if (out == null || out === v) return;
    autoSources.set(ta, v);
    autoOutputs.set(ta, out);
    restoreOf = v;
    appliedKind = 'auto';
    appliedText = out;
    writeTextarea(out);
