    const rect = panel.getBoundingClientRect();
    dragging = { x: e.clientX, y: e.clientY, left: rect.left, top: rect.top, moved: false, dx: 0, dy: 0 };
    panel.classList.add('thp-dragging');
    try { this.setPointerCapture(e.pointerId); } catch (err) {  }
    e.preventDefault();
  });
  jq(panel).on('pointermove' + NS, '.thp-handle', function (e) {
    if (!dragging) return;
    dragging.dx = e.clientX - dragging.x;
    dragging.dy = e.clientY - dragging.y;
    if (!dragging.moved && Math.abs(dragging.dx) + Math.abs(dragging.dy) > 3) dragging.moved = true;
    if (!dragging.moved || dragRaf) return;
    dragRaf = host.requestAnimationFrame(function () {
      dragRaf = 0;
      if (!dragging || !dragging.moved) return;

      const tx = clampN(dragging.left + dragging.dx, 4, Math.max(4, host.innerWidth - panel.offsetWidth - 4)) - dragging.left;
      const ty = clampN(dragging.top + dragging.dy, 4, Math.max(4, host.innerHeight - 40)) - dragging.top;
      panel.style.willChange = 'transform';
      panel.style.transform = 'translate(' + tx + 'px,' + ty + 'px)';
    });
  });
  function onDragEnd() {
    if (dragRaf) { host.cancelAnimationFrame(dragRaf); dragRaf = 0; }
    if (!dragging) return;
    const moved = dragging.moved;
    const base = { left: dragging.left, top: dragging.top };
    const dx = dragging.dx, dy = dragging.dy;
    dragging = null;
    panel.classList.remove('thp-dragging');
    if (!moved) return;

    const w = panel.offsetWidth;
    const left = clampN(base.left + dx, 4, Math.max(4, host.innerWidth - w - 4));
    const top = clampN(base.top + dy, 4, Math.max(4, host.innerHeight - 40));
    panel.style.transform = '';
    panel.style.willChange = '';
    panel.style.left = Math.round(left) + 'px';
    panel.style.top = Math.round(top) + 'px';
    const def = defaultPos();
    settings.panelOffset = {
      dx: Math.round(left - def.left),
      dy: Math.round(top - def.top)
    };
    saveSettings();

    setTimeout(function () {
      if (dragging) return;
      const ae = pdoc.activeElement;
      if (ae === ta || panel.contains(ae) || settingsEl.contains(ae)) return;
      hide();
    }, 400);
  }
  jq(panel).on('pointerup' + NS, '.thp-handle', onDragEnd);
  jq(panel).on('pointercancel' + NS, '.thp-handle', onDragEnd);
  jq(panel).on('dblclick' + NS, '.thp-handle', function () {
    settings.panelOffset = null;
    saveSettings();
    place();
  });

  let tDragging = null;
  let tRaf = 0;
  let tSuppressClick = false;
  jq(tbtn).on('pointerdown' + NS, function (e) {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const r = tbtn.getBoundingClientRect();
    tDragging = { x: e.clientX, y: e.clientY, left: r.left, top: r.top, moved: false, dx: 0, dy: 0 };
    tbtn.style.transition = 'none';
    try { this.setPointerCapture(e.pointerId); } catch (err) {}
    e.preventDefault();
  });
  jq(tbtn).on('pointermove' + NS, function (e) {
    if (!tDragging) return;
    tDragging.dx = e.clientX - tDragging.x;
    tDragging.dy = e.clientY - tDragging.y;
    if (!tDragging.moved && Math.abs(tDragging.dx) + Math.abs(tDragging.dy) > 3) {
      tDragging.moved = true;
      tSuppressClick = true;
      tbtn.classList.add('thp-dragging');
    }
    if (!tDragging.moved || tRaf) return;
    tRaf = host.requestAnimationFrame(function () {
      tRaf = 0;
      if (!tDragging || !tDragging.moved) return;
      const tw = tbtn.offsetWidth || 52;
      const th = tbtn.offsetHeight || 52;
      const tx = clampN(tDragging.left + tDragging.dx, 4, Math.max(4, host.innerWidth - tw - 4)) - tDragging.left;
      const ty = clampN(tDragging.top + tDragging.dy, 4, Math.max(4, host.innerHeight - th - 4)) - tDragging.top;
      tbtn.style.willChange = 'transform';
      tbtn.style.transform = 'translate(' + tx + 'px,' + ty + 'px)';
    });
  });
  function onToggleDragEnd() {
    if (tRaf) { host.cancelAnimationFrame(tRaf); tRaf = 0; }
    if (!tDragging) return;
    const moved = tDragging.moved;
    const base = { left: tDragging.left, top: tDragging.top };
    const dx = tDragging.dx, dy = tDragging.dy;
    tDragging = null;
    tbtn.style.transition = '';
    tbtn.classList.remove('thp-dragging');
    if (!moved) return;
    const tw = tbtn.offsetWidth || 52;
    const th = tbtn.offsetHeight || 52;
    const left = clampN(base.left + dx, 4, Math.max(4, host.innerWidth - tw - 4));
    const top = clampN(base.top + dy, 4, Math.max(4, host.innerHeight - th - 4));
    tbtn.style.transform = '';
    tbtn.style.willChange = '';
    tbtn.style.left = Math.round(left) + 'px';
    tbtn.style.top = Math.round(top) + 'px';
    settings.togglePos = { x: Math.round(left), y: Math.round(top) };
    saveSettings();
    setTimeout(function () { tSuppressClick = false; }, 60);
  }
  jq(tbtn).on('pointerup' + NS, onToggleDragEnd);
  jq(tbtn).on('pointercancel' + NS, onToggleDragEnd);
  jq(tbtn).on('dblclick' + NS, function () {
    settings.togglePos = null;
    saveSettings();
    placeToggle();
  });
  jq(tbtn).on('click' + NS, function () {
    if (tSuppressClick) { tSuppressClick = false; return; }
    if (menuOpen) closeMenu(); else openMenu();
  });

  let inputTimer = null;
  let updateRaf = 0, updateGuard = 0, composing = false;

  function scheduleUpdate(force) {
    host.clearTimeout(inputTimer);
    if (composing && !force) return;
    if (!ta) return;
    if (autoSilent(ta)) { scheduleAutoConvert(); return; }

    if (String(ta.value).length > 200) { inputTimer = host.setTimeout(update, 40); return; }
    if (updateRaf) return;
    const run = function () {
      if (!updateRaf) return;
      updateRaf = 0;
      host.clearTimeout(updateGuard);
      if (!composing) update();
    };
    updateRaf = host.requestAnimationFrame(run);
    updateGuard = host.setTimeout(run, 32);
  }

  pdoc.addEventListener('compositionstart', function (e) {
    if (e.target === ta) composing = true;
  }, { capture: true, signal: ac.signal });
  pdoc.addEventListener('compositionend', function (e) {
    if (e.target === ta) { composing = false; scheduleUpdate(true); }
  }, { capture: true, signal: ac.signal });
  function onInput() {

    if (editApplying) { editApplying = false; return; }

    if (ta.value === appliedText) return;
    appliedText = null;

    if (!ta.value.trim()) {

      if (appliedKind && restoreOf) pushHistory(restoreOf);
      else if (lastNonEmpty) pushHistory(lastNonEmpty);
      lastNonEmpty = null;
      manualClosed = false;
      restoreOf = null;
      appliedKind = null;
    } else {
      appliedKind = null;

      restoreOf = null;
      lastEdit = null;

      manualClosed = false;

      if (!lastNonEmpty || ta.value.length >= lastNonEmpty.length ||
        !lastNonEmpty.startsWith(ta.value)) {
        lastNonEmpty = ta.value;
      }
    }
    clearTimeout(inputTimer);

    if (autoSilent(ta)) { scheduleAutoConvert(); return; }

    const pending = panel.querySelector('.thp-kind-tip');
    if (!panel.classList.contains('thp-show') || pending) update();
    else scheduleUpdate();
  }

  function onFocus(el) {

    const self = el || mainTa;
    if (self && ta !== self) switchActiveTarget(self);

    if (skipFocusOpen) { skipFocusOpen = false; return; }
    manualClosed = false;

    if (!settings.focusOpen) return;
    update();
  }

  function softKeyboardOpen() {
    try {
      const vv = host.visualViewport;
      if (!vv || !vv.height) return false;
      const gap = host.innerHeight - vv.height;
      return gap > Math.max(120, host.innerHeight * 0.22);
    } catch (e) { return false; }
  }
  function onBlur() {
    setTimeout(function () {
      if (dragging || tDragging) return;

      if (Date.now() < panelInteractUntil) {

        setTimeout(onBlur, Math.max(30, panelInteractUntil - Date.now() + 30));
        return;
      }

      if (softKeyboardOpen()) return;
      if (settingsOpen || historyOpen || menuOpen || contOpen) return;

      const ae = pdoc.activeElement;
      if (ae === ta || panel.contains(ae) || settingsEl.contains(ae) ||
        historyEl.contains(ae) || menuEl.contains(ae) || contEl.contains(ae)) return;
      if (focusedInTargets()) return;

      if (ta !== mainTa && mainTa && mainTa.isConnected &&
        panel.classList.contains('thp-show') && !manualClosed) {
        switchActiveTarget(mainTa);
        update();
        return;
      }
      hide();
    }, 220);
  }

  function onKeyDown(e) {

    if (e.key === 'Escape') {
      if (settingsEl.querySelector('.thp-help[open]')) {
        e.preventDefault();
        closeSettingsHelp();
        return;
      }
      if (contOpen) {
        e.preventDefault();
        closeCont();
        return;
      }
      if (settingsOpen) {
        e.preventDefault();
        closeSettings();
        return;
      }
      if (historyOpen) {
        e.preventDefault();
        closeHistory();
        return;
      }
      if (menuOpen) {
        e.preventDefault();
        closeMenu();
        return;
      }
      if (panel.classList.contains('thp-show')) {
        manualClosed = true;
        hide();
      }
      return;
    }

    const digits = /^Digit([1-5])$/.exec(e.code || '');
    if (settings.altDigits && e.altKey && digits && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
      if (!panel.classList.contains('thp-show')) return;

      const want = parseInt(digits[1], 10);
      const hitRow = Array.prototype.filter.call(rowsEl.querySelectorAll('.thp-row'), function (r) {
        const badge = r.querySelector('.thp-idx');
        return badge && badge.textContent === String(want);
      })[0];
      const kind = hitRow && hitRow.getAttribute('data-kind');
      if (kind) { e.preventDefault(); applyPick(kind); }
      return;
    }

    const combo = comboOf(e);
    if (!combo) return;
    const hk = settings.hotkeys || {};
    const shown = panel.classList.contains('thp-show');
    if (combo === hk.applyPinyin) {
      if (shown) { e.preventDefault(); applyPick('pinyin'); }
      return;
    }
    if (combo === hk.applyHarmonic) {
      if (shown) { e.preventDefault(); applyPick('harmonic'); }
      return;
    }
    if (combo === hk.applyFusion) {
      if (shown) { e.preventDefault(); applyPick('fusion'); }
      return;
    }
    if (combo === hk.applyMix) {
      if (shown) { e.preventDefault(); applyPick('mix'); }
      return;
    }
    if (combo === hk.applyCombo) {
      if (shown) { e.preventDefault(); applyPick('combo'); }
      return;
    }
    if (combo === hk.regen) {
      if (shown) {
        e.preventDefault();
        bumps.harmonic++;
        bumps.fusion++;
        bumps.mix++;
        bumps.combo++;
        bumps.encode++;
        bumps.english++;
        rerender();
      }
      return;
    }
    if (combo === hk.close) {
      if (shown) {
        e.preventDefault();
        manualClosed = true;
        hide();
      }
    }
  }

  function bindTextarea(el) {
    const node = el || ta;

    jq(node)
      .off(NS)
      .on('input' + NS, function () { if (node.isConnected && ta === node) onInput(); })

      .on('focus' + NS, function () { if (node.isConnected) onFocus(node); })
      .on('blur' + NS, function () { if (node.isConnected && ta === node) onBlur(); })
      .on('keydown' + NS, function (e) { if (node.isConnected && ta === node) onKeyDown(e); });
  }

  function ensureMainTa() {
    let cur = null;
    try { cur = pdoc.getElementById('send_textarea'); } catch (e) { return; }
    if (!cur || (cur === mainTa && mainTa.isConnected)) return;
    try { if (mainTa) jq(mainTa).off(NS); } catch (e) {}
    for (let i = targets.length - 1; i >= 0; i--) {
      if (!targets[i].el || !targets[i].el.isConnected) targets.splice(i, 1);
    }
    mainTa = cur;
    bindTextarea(cur);
    if (!ta || !ta.isConnected) {
      switchActiveTarget(cur);
      manualClosed = false;

      if (settings.focusOpen && pdoc.activeElement === cur) update();
    }
  }

  function onViewportChange() {
    if (panel.classList.contains('thp-show')) place();
    placeToggle();
    if (settingsOpen) placeSettings();
    if (historyOpen) placeHistory();
    if (menuOpen) placeMenu();

    if (contOpen) placeCont();
  }
  host.addEventListener('resize', onViewportChange, { signal: ac.signal });

  let placeGuardTimer = 0;
  let placeGuardStopped = false;
  const placeGuard = function () {
    if (placeGuardStopped) return;
    placeGuardTimer = host.setTimeout(function () {
      placeGuardTimer = 0;
      if (placeGuardStopped) return;
      try {
        if (!panel.classList.contains('thp-show') || !ta || !ta.isConnected || dragging) return;
        const r = targetRect();
        const p = panel.getBoundingClientRect();
        const want = r.top - p.height - 8;

        const drifted = Math.abs(p.bottom - (r.top - 8)) > 12;
        let conflict = false;
        if (mainTa && mainTa.isConnected) {
          try {
            const mr = mainTa.getBoundingClientRect();
            conflict = mr.height > 0 && p.bottom > mr.top - 4 && p.top < mr.bottom + 4;
          } catch (e) { conflict = false; }
        }
        if (drifted || conflict) place();
      } catch (e) {  }
      placeGuard();
    }, 220);
  };
  placeGuard();

  let scrollRaf = 0;
  const onScrollReposition = function () {
    if (scrollRaf) return;
    scrollRaf = host.requestAnimationFrame(function () {
      scrollRaf = 0;
      if (!panel.classList.contains('thp-show') || !ta || !ta.isConnected) return;

      if (ta !== mainTa && mainTa && mainTa.isConnected) {
        let conflict = false;
        try {
          const p = panel.getBoundingClientRect();
          const m = mainTa.getBoundingClientRect();
          conflict = m.height > 0 && p.bottom > m.top - 4 && p.top < m.bottom + 4;
        } catch (e) { conflict = false; }
        if (conflict) {
          switchActiveTarget(mainTa);
          update();
          return;
        }
      }
      place();
    });
  };
  pdoc.addEventListener('scroll', onScrollReposition, { capture: true, passive: true, signal: ac.signal });
  host.addEventListener('scroll', onScrollReposition, { capture: true, passive: true, signal: ac.signal });
  placeToggle();
  if (host.visualViewport) {
    host.visualViewport.addEventListener('resize', onViewportChange, { signal: ac.signal });
  }

  let instanceStopped = false;
  let bootTimer = 0;
  let tries = 0;
  (function boot() {
    if (instanceStopped) return;
    const el = pdoc.getElementById('send_textarea');
    if (el) {
      mainTa = el;
      ta = el;
      bindTextarea();

      if (pdoc.activeElement === el) update();
      startCardScan();

      try { bootRescue(); } catch (e) {}

      try { installDiagCapture(); } catch (e) {}

      try { diagNetInstall(); } catch (e) {}

      try {
        const tauriApp = host.__TAURI__ && host.__TAURI__.app;
        if (tauriApp && typeof tauriApp.getVersion === 'function') {
          Promise.resolve(tauriApp.getVersion()).then(function (v) {
            diagTTVersion = String(v || '');
          }).catch(function () {});
        } else {

          const st = host.SillyTavern;
          const v = st && (st.version ||
            (typeof st.getContext === 'function' && st.getContext() && st.getContext().version));
          if (typeof v === 'string' && v) diagTTVersion = v;
        }
      } catch (e) {}

      try { obfRecover(); } catch (e) {}
      try { obfBindEvents(); } catch (e) {}
      try { rspSync(); } catch (e) {}

      try { sweepLegacyMarks(); } catch (e) {}
      return;
    }
    if (++tries < 120) bootTimer = setTimeout(boot, 250);
  })();

  function cleanup() {
    if (instanceStopped) return;
    instanceStopped = true;
    try { host.clearTimeout(bootTimer); bootTimer = 0; } catch (e) {}
    obfEventAlive = false;
    obfEventUnbinders.forEach(function (unbind) {
      try { unbind(); } catch (e) {}
    });
    obfEventUnbinders.length = 0;

    try { flushSettings(); } catch (e) {}
    try { rspUninstall(); } catch (e) {}
    try { diagNetUninstall(); } catch (e) {}
    rspDiagEvents.length = 0;
    ac.abort();
    host.clearTimeout(cardScanTimer);
    host.clearTimeout(inputTimer);
    host.clearTimeout(autoTimer);
    host.clearTimeout(wbTimer);
    host.clearTimeout(selDebounce);
    try { host.cancelAnimationFrame(scrollRaf); } catch (e) {}
    placeGuardStopped = true;
    try { host.clearTimeout(placeGuardTimer); } catch (e) {}

    try { if (rescueTimer) host.clearInterval(rescueTimer); rescueTimer = 0; } catch (e) {}
    try { const r = pdoc.getElementById(RESCUE_ID); if (r && r.parentNode) r.parentNode.removeChild(r); } catch (e) {}
    try { host.clearTimeout(akManualWatchdog); akManualWatchdog = 0; } catch (e) {}

    try { obfClearSentTimer(); } catch (e) {}
    try { arClearVerifyTimers(); } catch (e) {}
    try { host.clearTimeout(obfUndoTimer); obfUndoTimer = 0; } catch (e) {}
    try {
      contJob = null;
      contAfterJob = null;
      contReasoningJob = null;
      contDropUndo = null;
      host.clearTimeout(contUntangleTimer);
      contUntangleTimer = 0;
      contClearLate();
    } catch (e) {}
    for (const t of targets) {
      try {
        t.el.removeEventListener('input', t.hIn);
        t.el.removeEventListener('keydown', t.hKey);
        t.el.removeEventListener('focusout', t.hOut);
        if (t.hSel) t.el.removeEventListener('select', t.hSel);
      } catch (e) {}
    }
    try { if (mainTa) jq(mainTa).off(NS); } catch (e) {}
    jq(panel).off(NS);
    jq(tbtn).off(NS);
    jq(settingsEl).off(NS);
    jq(menuEl).off(NS);
    jq(historyEl).off(NS);
    jq(contEl).off(NS);
    panel.remove();
    styleEl.remove();
    tbtn.remove();
    settingsEl.remove();
    menuEl.remove();
    historyEl.remove();
    contEl.remove();

    if (diagCaptureHandlers) {
      try { diagCaptureHandlers.host.removeEventListener('error', diagCaptureHandlers.onHostError); } catch (e) {}
      try { diagCaptureHandlers.host.removeEventListener('unhandledrejection', diagCaptureHandlers.onHostRej); } catch (e) {}
      if (diagCaptureHandlers.win) {
        try { diagCaptureHandlers.win.removeEventListener('error', diagCaptureHandlers.onFrameError); } catch (e) {}
        try { diagCaptureHandlers.win.removeEventListener('unhandledrejection', diagCaptureHandlers.onFrameRej); } catch (e) {}
      }
      diagCaptureHandlers = null;
    }
    try { window.removeEventListener('pagehide', stopInstance); } catch (e) {}
    try { window.removeEventListener('unload', stopInstance); } catch (e) {}
    for (let i = 0; i < iframeDocs.length; i++) {
      try { iframeDocs[i].removeEventListener('focusin', onIframeFocusin, true); } catch (e) {}
    }
    iframeDocs.length = 0;
    try {
      const frames = pdoc.querySelectorAll('iframe');
      for (let i = 0; i < frames.length; i++) {
        try { delete frames[i].__thpBoundDoc; } catch (e) {}
      }
    } catch (e) {}
    try { delete host.__thpObf; } catch (e) {}
    try { delete host.__thpRsp; } catch (e) {}
    try { if (typeof Symbol === 'function') delete host[Symbol.for('thp.diag.shared')]; } catch (e) {}
    try { delete host.__thpPinyinImeInstance; } catch (e) {}
  }
  function stopInstance() { cleanup(); }
  try { host.__thpPinyinImeInstance = { stop: stopInstance }; } catch (e) {}
  host.setTimeout(function () { try { updAutoMaybe(); } catch (e) {} }, 3000);
  window.addEventListener('pagehide', stopInstance, { signal: ac.signal });
  window.addEventListener('unload', stopInstance, { signal: ac.signal });
})();
